(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["moe"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-grouped-gemm-tcgen05"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-1\">一 · 事故现场：一次专家批处理下的逐专家 launch 崩盘</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-2\">二 · 算法要解决的具体问题：把碎 M 维重新拼大</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-3\">三 · 适用边界的量化判据：Util 与专家分布</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-4\">四 · 机制步骤与段间气泡：一次 launch 的内部时序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-5\">五 · 它不解决什么：三条明确的排除线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-6\">六 · 工程判断：先量分布，再决定拼不拼</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-7\">七 · 事故现场：当 256 个专家各开一个 kernel</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-8\">八 · 段元数据的收集与偏移表构建</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-9\">九 · 拼接为统一 A 矩阵的物理布局</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-10\">十 · tcgen05 MMA 的按段执行与指针切换</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-11\">十一 · 结果写回与输出缓冲的对应关系</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-12\">十二 · 资源释放与进入下一层的衔接</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-13\">十三 · 段边界如何吃掉收益：偏移表、尾部空转与段间气泡</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-14\">十四 · 分段矩阵乘公式：逐项拆解与偏移语义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-15\">十五 · 利用率公式：tile 尾部浪费的定量来源</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-16\">十六 · 2-SM 协作对 M 维的补偿：为什么小段仍能打满</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-17\">十七 · 伪代码落到可实现：偏移表与段循环的数据结构</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-18\">十八 · 量化叠加下的公式变形：$K$ 维与缩放因子的位置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-19\">十九 · 从公式到容量判断：三个可计算的量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-20\">二十 · 分段矩阵乘的边界：Util 何时塌陷、偏移表何时压垮占用率</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-21\">二十一 · 请求形态的匹配：批内多专家并发是前提</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-22\">二十二 · 长度分布：解码与预填的段长结构差异</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-23\">二十三 · 并发与批大小：甜区与两侧的退化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-24\">二十四 · 负载不对时的三种失败模式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-25\">二十五 · 配方落地：把负载特征映射到 kernel 参数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-26\">二十六 · 负载配方：什么请求形态喂得饱分组 GEMM</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-27\">二十七 · 硬件档位：2-SM 协作的占用率边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-28\">二十八 · 并行拓扑：专家段跨 SM 的切分与偏移表放置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-29\">二十九 · 量化方案：NVFP4/FP8 与分段累加的数值对齐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-30\">三十 · KV 策略：分组 GEMM 与分页 KV 的显存共存</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-31\">三十一 · 调度参数：batch 组装与段顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-32\">三十二 · 可复现的配置思路：从约束到参数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-33\">三十三 · 配方边界：Util 跌破五成时该退到哪里</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-34\">三十四 · 显存与带宽：拼接矩阵的驻留代价与分段流水的读带宽</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-35\">三十五 · 通信：单 kernel 融合对集合通信窗口的压缩</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-36\">三十六 · 功耗与占用率：偏移表的寄存器-共享内存税</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-37\">三十七 · 尾延迟：max_e M_e 决定的分段长度与 SLO 抖动</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-38\">三十八 · 规模上去以后哪里先崩：三条曲线的交点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-39\">三十九 · 规模上去以后，先崩的是利用率而不是算力</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-40\">四十 · 精度漂移：分段累加与量化叠加的失配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-41\">四十一 · OOM 的三条路径：TMEM、共享内存、偏移表</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-42\">四十二 · 批抖动与路由不均：Util 的实时观测</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-43\">四十三 · 段间气泡：指针切换与清零的同步窗口</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-44\">四十四 · 监控面与回滚阶梯</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-45\">四十五 · 段间气泡与占用率塌陷：分组 GEMM 的四类失效面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-46\">四十六 · 同族算法的坐标系：三种切分粒度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-47\">四十七 · 决策表：四条判据与适用条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-48\">四十八 · 段间同步：tcgen05 方案独有的选择维度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-49\">四十九 · 与量化、KV、并行的交叉适用条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-50\">五十 · 选型后的容量口径：把 Util 换算成 SLO</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-51\">五十一 · 边界条件的硬判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-grouped-gemm-tcgen05-sec-52\">五十二 · 分组 GEMM 的邻域坐标：何时选它，何时换手</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:482px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 482.0 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">收集各专家 token 块，记录每段偏移与长度</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">按专家顺序拼接为统一 A 矩阵（M_total×K）</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">tcgen05 MMA 按段切换 B 权重指针，TMEM 累加器分段清零</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">每段完成后将结果写回对应 token 的输出缓冲</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">释放 TMEM 与共享内存，进入下一层</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-1\">一 · 事故现场：一次专家批处理下的逐专家 launch 崩盘</h3>\n<p>某个 MoE 推理服务在 Blackwell 单机上跑 64 专家的解码层，router 每步把 batch 内 token 分给各专家。工程团队最初按最直白的写法实现：对每个非空专家单独发一次 GEMM kernel，权重指针直接指向该专家切片。离线压测时 batch 小、专家命中稀疏，看不出问题；上线后进入持续批处理，batch 被填到几十个 token，几乎每个专家都非空，于是每层要连续发 64 次 kernel launch。现象不是算得慢，而是 GPU 时间线上出现密集的空隙：每次 launch 的 CPU 侧提交、参数打包、流同步把张量核心切成碎片，单层 GEMM 时延随专家数线性抬升，端到端 SLO 直接被打穿。更糟的是，每个专家的 token 数往往只有个位数到十几个，M 维远小于 tcgen05 单次 MMA 所需的规模，张量核心在绝大多数 tile 上处于半空转状态。</p>\n<p>这个事故的根因可以精确写成一句话：MoE 每个专家是独立的小矩阵乘，逐专家 launch 同时付出了 kernel 启动开销与 tile 利用率两笔代价，而 Blackwell 的 tcgen05 张量核心需要足够大的 M 维才能打满算力。两笔代价在专家数多、单专家 token 块偏小的场景里叠加，不是靠调大 batch 能消掉的——batch 再大，router 的分配仍然把 M 维切碎到各专家名下。</p>\n\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-2\">二 · 算法要解决的具体问题：把碎 M 维重新拼大</h3>\n<p>tcgen05 分组 GEMM 专家批处理针对的正是上述切碎。它把所有专家的 token 块按专家顺序拼成一个统一的大 M 维矩阵，一次 launch 覆盖全部专家，用分段的方式在同一个 kernel 内依次完成各专家的矩阵乘。形式化地，设第 $s$ 个专家在拼接矩阵中的 token 段起止偏移为 $m_s$，则该段计算为</p>\n<div class=\"formula\">$$Y[m_s:m_{s+1},:]=A[m_s:m_{s+1},:]\\cdot B_s$$</div>\n<p>其中 $A$ 是拼接后的统一激活矩阵（$M_{total}\\times K$），$B_s$ 是该专家权重，累加器驻留 TMEM。注意这里的 M 维是 $M_{total}$ 而非单个专家的 $M_e$：kernel 只需一次网格启动，段间切换的是 B 权重指针与 TMEM 累加器的清零边界，而不是重新走一遍 launch 路径。这就是它消除 CPU 启动开销与流水线气泡的机制来源。</p>\n<p>它真正解决的问题边界很窄，必须说清楚：<strong>它解决的是「同一层内多专家并发、单专家 token 块偏小」时的 launch 开销与 M 维不足</strong>，不解决专家间负载不均本身，不解决 router 的容量因子与令牌丢弃策略（那是路由侧条目的话题），也不解决专家权重与分页 KV 争抢显存的问题。它更不是通用 GEMM 的替代品：当某一层只有单个专家或 M 维本来就足够大时，拼接带来的偏移表维护成本换不回任何收益，直接发一个普通 GEMM 更划算。</p>\n\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-3\">三 · 适用边界的量化判据：Util 与专家分布</h3>\n<p>判断一个 MoE 层该不该走这条路，工程上有一个可算的判据。设专家数为 $E$，第 $e$ 个专家的 token 数为 $M_e$，tile 的 M 维粒度为 $\\text{tile}_M$，则拼接后张量核心的利用率为</p>\n<div class=\"formula\">$$\\text{Util}=\\frac{\\sum_e M_e}{E\\cdot\\lceil \\max_e M_e/\\text{tile}_M\\rceil\\cdot \\text{tile}_M},\\quad \\text{GEMM 吞吐}\\propto \\text{Util}\\cdot\\text{TC 峰值}$$</div>\n<p>分母的含义是：若按最大专家所需的 tile 数为每个专家预留同样多的 tile 槽位，则总槽位是 $E$ 倍的最大专家槽位。分子是真实有效 token 数。两者之比就是被有效填充的比例。这个式子直接给出适用边界：专家 token 数越均匀，Util 越接近 1；分布越偏，尾部空转越多。给定事实明确指出，专家 token 数差异大时 tile 尾部浪费严重，Util 可能低于 50%——这意味着即便 kernel 只发一次，张量核心仍有近一半时间在算零。</p>\n<p>由此得到三条工程判据。其一，专家数多且单专家 token 块偏小，是这条路的甜点区：单专家 M 维小到无法打满 tcgen05 时，2-SM 协作模式把两个 SM 的算力合到一个专家段上，补偿小 M 维，这是它与普通 grouped GEMM 的关键差别。其二，专家分布若长尾极重，拼接矩阵的 tile 尾部大量空转，收益会被 Util 的塌陷吃掉，此时应回到路由侧做容量控制而不是在这里硬拼。其三，规模上限受共享内存与寄存器约束：偏移表与段元数据随专家数线性增长，专家数增大时寄存器与共享内存压力线性上升，材料未给出具体专家数上限，因此容量规划必须按实测占用率反推，而不能假定专家数可以无限加。</p>\n\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-4\">四 · 机制步骤与段间气泡：一次 launch 的内部时序</h3>\n<p>把算法拆成可实现的步骤，才能看清代价落在哪里。第一步，收集各专家 token 块，记录每段偏移与长度，形成偏移表；第二步，按专家顺序把 token 块拼接为统一 A 矩阵（$M_{total}\\times K$），这一步是纯数据搬运，代价是额外的共享内存与带宽占用；第三步，tcgen05 MMA 按段推进，每到段边界切换 B 权重指针，并对 TMEM 累加器分段清零；第四步，每段完成后把结果写回对应 token 的输出缓冲；第五步，释放 TMEM 与共享内存，进入下一层。</p>\n<p>代价的分布很具体。偏移表本身要常驻寄存器或共享内存，专家数增大时线性膨胀，直接压缩可用的占用率，进而影响能同时驻留的 CTA 数——这是吞吐侧的隐性税。段间切换 B 指针与 TMEM 清零若同步不当，会在段与段之间插入气泡，抵消单 kernel 融合的收益；这是失败模式之一，工程上必须让段切换与上一段的写回重叠，而不是串行等待。写回阶段则是纯带宽开销：每段结果要落到各自 token 的输出缓冲，段越碎，写回越零散，有效带宽越低。延迟侧，单层 GEMM 时延由「最长专家段的 MMA 时间 + 段切换开销 × 段数 + 写回」构成，段数即非空专家数，因此专家命中越密，切换开销越不可忽略。</p>\n<p>一个具体例子：某层 64 专家、batch 内 200 个 token，router 分配后最大专家拿到 20 个 token，其余专家各几个。逐专家 launch 要发 64 次 kernel，每次 M 维只有个位数，tcgen05 几乎打不满；拼接后一次 launch，$M_{total}=200$，2-SM 模式让每个小专家段跨两个 SM 协作，张量核心在段内被填满。但若最大专家拿到 120 个 token 而其余专家合计 80 个，按最大专家预留槽位算，Util 会明显下滑，尾部 tile 空转——同一个算法，在两种分布下一个赚一个亏，边界就在分布均匀度上。</p>\n\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-5\">五 · 它不解决什么：三条明确的排除线</h3>\n<p>第一条排除线是路由决策。分组 GEMM 只接受 router 已经给出的分配结果，它不改变容量因子、不做令牌丢弃、不重排专家选择；这些属于路由侧条目的主题，本算法在其下游。若分配本身把 token 堆到少数专家，拼接矩阵的尾部浪费是路由问题的投影，不是 GEMM 能修的。</p>\n<p>第二条排除线是显存共存。专家权重与分页 KV 的显存争抢、权重的换入换出策略，不在本算法的职责内；它只假设权重指针在段切换时可寻址。若权重被换出导致段切换时指针失效，问题出在显存管理层，拼接 kernel 无能为力。</p>\n<p>第三条排除线是量化本身。分组 GEMM 可与 NVFP4/FP8 权重叠加，但微缩放量化的数值格式与缩放因子布局由量化侧条目定义；本算法只负责在段边界正确切换已量化权重的指针与累加器清零，不负责量化误差控制。把这三条线划清，才能避免在错误的层上做优化：launch 开销与 M 维填充是本算法的唯一战场。</p>\n\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-6\">六 · 工程判断：先量分布，再决定拼不拼</h3>\n<p>落到工程决策上，第一步不是改 kernel，而是采集每层每专家的 token 数分布，按上面的 Util 公式离线估算。若 Util 长期高于某个可接受阈值且非空专家数足以摊薄 launch 开销，拼接是净赚；若 Util 因长尾塌陷，应先动路由侧容量控制，或对该层退回逐专家 launch 并接受其开销。第二步是检查偏移表的寄存器与共享内存占用随专家数的增长曲线，确认占用率不会因元数据膨胀而掉档——这是规模上限的真实约束，材料未给具体上限，必须实测。第三步是验证段切换与写回的同步：段间气泡是本算法最隐蔽的失败模式，它不会让结果出错，只会让单 kernel 融合的收益悄悄归零，因此单层 GEMM 时延的分解测量比端到端吞吐更能暴露问题。</p>\n<p>一句话的工程判断：tcgen05 分组 GEMM 专家批处理是一把针对「专家多、单专家 M 维小」的专用工具，它的收益来自一次 launch 与 2-SM 协作对小 M 维的补偿，它的风险来自专家分布长尾导致的 tile 尾部空转与偏移表膨胀。把它用在分布均匀的层上是纯赚，用在长尾层上则是把 launch 开销换成了空转开销——两者都不便宜，区别只在于你是否先量过分布。</p>\n\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-7\">七 · 事故现场：当 256 个专家各开一个 kernel</h3>\n<p>某线上推理集群在一次路由分布漂移后出现单层 MoE 时延翻倍：router 把 batch 内 token 高度集中到少数热门专家，其余专家只分到个位数 token。原实现按专家逐个 launch 小 GEMM，每个 kernel 的 M 维常常只有几十行，远低于 tcgen05 打满张量核心所需的规模；同时每层要发出与专家数同量级的 kernel，CPU 侧启动开销与流水线气泡叠加，GPU 在两次 launch 之间空转。这不是算子写错，而是<b>逐专家 launch 的结构性代价</b>：启动开销固定，而每个专家的有效计算量随路由波动，二者无法匹配。分组 GEMM 专家批处理正是为这个场景设计的——把整层所有专家的 token 块拼成一个统一 A 矩阵，一次 launch 覆盖全部专家。</p>\n<p>它解决的问题边界很清晰：MoE 层内多专家并发、单专家 token 块偏小、SLO 盯住单层 GEMM 时延。机制上，先收集各专家 token 块并记录偏移与长度，按专家顺序拼接为 $M_{total}\\times K$ 的 A 矩阵，tcgen05 MMA 按段切换 B 权重指针、TMEM 累加器分段清零，每段结果写回对应 token 输出缓冲，最后释放 TMEM 与共享内存进入下一层。核心是分段矩阵乘：</p>\n<div class=\"formula\">$$Y[m_s:m_{s+1},:]=A[m_s:m_{s+1},:]\\cdot B_s$$</div>\n<p>其中 $m_s$ 是第 $s$ 个专家段的起止偏移，$B_s$ 为该专家权重。它<b>不解决</b>的问题同样明确：不改变路由本身的负载不均，不减少专家权重的显存占用，也不适用于专家数极少、单专家 M 维本就足够大的层——那种情形下拼接收益被偏移表开销吃掉。</p>\n<p>失效条件集中在分布与规模两端。专家 token 数差异大时，拼接矩阵按最大段对齐 tile，尾部大量空转：</p>\n<div class=\"formula\">$$\\text{Util}=\\frac{\\sum_e M_e}{E\\cdot\\lceil \\max_e M_e/\\text{tile}_M\\rceil\\cdot \\text{tile}_M},\\quad \\text{GEMM 吞吐}\\propto \\text{Util}\\cdot\\text{TC 峰值}$$</div>\n<p>Util 可能跌破 50%，此时单 kernel 融合省下的 launch 开销抵不过张量核心空转。专家数增多则使偏移表与段元数据膨胀，寄存器与共享内存压力线性增长，占用率下降；分段切换 B 指针与 TMEM 清零若同步不当，段间气泡会直接抵消融合收益。工程判断：先看路由分布的 max/mean 比与专家数，再决定是否启用；分布长尾严重时应配合 capacity factor 截断或 token 重排，而不是硬扛分组 GEMM。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>分组 GEMM 收益</th><th>主要代价</th></tr></thead><tbody><tr><td>专家多、单专家 M 小且分布均匀</td><td>消除逐专家 launch，2-SM 补偿小 M</td><td>偏移表元数据</td></tr><tr><td>分布长尾、max/mean 高</td><td>有限</td><td>tile 尾部空转，Util &lt; 50%</td></tr><tr><td>专家数极大</td><td>递减</td><td>寄存器/共享内存压力线性上升</td></tr></tbody></table>\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-8\">八 · 段元数据的收集与偏移表构建</h3>\n<p>分组 GEMM 的第一步不是算，而是“记账”。一个 MoE 层内，router 已经把 batch 内每个 token 指派给了若干专家，此时 kernel 侧拿到的是若干条（token 索引，专家 id）的映射。要在一次 launch 内覆盖全部专家，必须先把这些散落的 token 按专家归拢，形成一张偏移表：第 s 段起始偏移 $m_s$、段长 $\\ell_s=m_{s+1}-m_s$、以及该段对应的权重基址指针。这一步的输入是 router 输出的指派结果与各专家的 token 计数，输出是一张长度为 $E+1$ 的前缀和数组（$E$ 为专家数）加上一份 B 权重指针表。</p>\n<p>代价落在两处。其一是前缀和的串行性：$E$ 个计数做一次 exclusive scan，本身极轻，但它必须发生在任何 MMA 之前，属于关键路径上的纯延迟项，在解码这种单层时延以微秒计的形态里不可忽略。其二是元数据的驻留成本：偏移表与指针表要常驻寄存器或共享内存，长度随 $E$ 线性增长，$E$ 增大时占用率随之下降，这正是该机制规模上限受共享内存与寄存器约束的直接来源。工程上常见的做法是把偏移表放在共享内存的固定槽位、指针表用常量内存或 kernel 参数传入，避免每个线程各持一份。</p>\n<p>具体例子：一个 batch 内 4096 个 token、top-2 路由、$E=64$ 的 MoE 层，收集后得到 8192 条指派，按专家排序后前缀和数组 65 项。若平均每专家 128 个 token，则段长整齐；若分布倾斜到个别专家拿到上千 token，偏移表本身不变，但后面 tile 化的浪费会立刻显现——记账这一步只暴露分布，不解决分布。</p>\n\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-9\">九 · 拼接为统一 A 矩阵的物理布局</h3>\n<p>有了偏移表，第二步是把各专家的 token 激活按专家顺序物理拼接成一个 $M_{total}\\times K$ 的统一 A 矩阵。注意这里的“拼接”是逻辑与物理同时发生的：token 在 HBM 中的原始位置是乱的，必须做一次 gather（或让上游 router 直接按专家序写入），把第 s 段放在行区间 $[m_s,m_{s+1})$ 上。输出是连续、按专家分段有序的 A，输入是原始激活加偏移表。</p>\n<p>这一步的代价是纯带宽。gather 要读一遍原始激活、写一遍拼接后的 A，$M_{total}\\times K$ 个元素各走两次 HBM，若 $K$ 为隐藏维、精度为 FP8，则搬运量与 $M_{total}K$ 成正比。在预填阶段 $M_{total}$ 大、这笔搬运被 GEMM 本身的计算量摊薄；在解码阶段 $M_{total}$ 小但每层都要重做一次，搬运延迟占比上升。规避手段是让上游直接产出专家序布局，把 gather 融进 router 或前一个算子，省掉一次往返。</p>\n<p>分段矩阵乘的形式在这里定下来：</p>\n<div class=\"formula\">$$Y[m_s:m_{s+1},:]=A[m_s:m_{s+1},:]\\cdot B_s,\\quad s=0,\\dots,E-1$$</div>\n<p>其中 $B_s$ 是第 s 个专家的权重，累加器驻留 TMEM。这个式子说明 A 的切分边界必须与偏移表严格一致，任何一行错位都会让某段结果写到错误的 token 输出缓冲上——这也是为什么偏移表要用前缀和而非独立计数，前缀和天然保证了段与段之间无缝且不重叠。</p>\n<p>具体例子：$K=7168$、FP8、8192 行拼接 A，搬运量约 8192×7168 字节量级，在 NVLink 5 级别的片内带宽下是百微秒量级的动作；若把它融进上游写回，这百微秒可以整体消失。</p>\n\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-10\">十 · tcgen05 MMA 的按段执行与指针切换</h3>\n<p>第三步是真正的计算：tcgen05 MMA 沿 A 的行方向推进，每进入一个新段就切换 B 权重指针，并把 TMEM 累加器分段清零。这里的机制要点有两个。其一是 2-SM 协作模式：单个专家的 M 维（$\\ell_s$）往往远小于打满张量核心所需的 M，2-SM 模式让两个 SM 共同承担一段的 MMA，把有效 M 维翻倍，从而在小段上仍能喂饱张量核心。其二是 TMEM 分段清零：累加器是跨段复用的物理资源，段与段之间必须清零，否则上一段的残值会污染下一段。</p>\n<p>代价的核心是段间气泡。切换 B 指针、清零 TMEM、等待流水线排空，这三件事若串行执行，就在每段之间插入一段空转；$E$ 越大，气泡总数越多，单 kernel 融合省下的 launch 开销可能被这些气泡吃掉。工程上的做法是把清零与下一段的 A 预取重叠、把指针切换做成描述符预置而非运行时改写，让 MMA 流水线在段边界上尽量不停。另一个代价是 tile 尾部浪费：段长 $\\ell_s$ 不是 tile_M 的整数倍时，最后一个 tile 只填了一部分行，张量核心仍在按整 tile 的节拍工作。</p>\n<p>利用率公式把这件事量化：</p>\n<div class=\"formula\">$$\\text{Util}=\\frac{\\sum_e M_e}{E\\cdot\\lceil \\max_e M_e/\\text{tile}_M\\rceil\\cdot \\text{tile}_M},\\quad \\text{GEMM 吞吐}\\propto \\text{Util}\\cdot\\text{TC 峰值}$$</div>\n<p>分母按最大专家段对齐到 tile 上界，意味着所有段都被隐式地按最坏段长计费；分子是真实 token 总量。分布越均匀，Util 越接近 1；分布越倾斜，分母被最大段撑大而分子不变，Util 下滑。定性地说，专家 token 数差异大时 Util 可能跌破 50%，此时即便 TC 峰值再高，有效吞吐也只有一半。</p>\n<p>具体例子：$E=64$、tile_M 取 128、平均段长 128 但最大段长 1024，则分母为 $64\\times\\lceil1024/128\\rceil\\times128=64\\times8\\times128$，分子为 $64\\times128$，Util 落到约八分之一量级——这就是倾斜分布下分组 GEMM 的真实处境，也是容量因子类手段存在的理由（此处不展开，见同模块对应条目）。</p>\n\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-11\">十一 · 结果写回与输出缓冲的对应关系</h3>\n<p>第四步是把每段算完的 $Y$ 写回对应 token 的输出缓冲。输入是 TMEM 中该段的累加结果，输出是按原始 token 顺序排列的激活（或按 router 组合权重前的专家输出）。这里存在一次“逆 gather”：A 是按专家序拼的，输出若要求按原 token 序，就得用偏移表反查每个 token 落在哪一段的哪一行，再散射写回。</p>\n<p>代价是写回带宽加索引开销。写回量与 $M_{total}\\times N$ 成正比（$N$ 为输出维），散射写回的访存模式不如连续写友好，在 HBM 上会产生额外的行激活开销。更关键的是同步：写回必须在 TMEM 清零之前完成，否则数据丢失；而写回又要与下一段的 MMA 重叠才能藏住延迟，这就把 TMEM 的生命周期管理变成了一个显式的依赖图问题。工程上通常用双缓冲 TMEM 分区，让第 s 段写回与第 s+1 段累加并行。</p>\n<p>具体例子：top-2 路由下，同一个 token 会出现在两个专家段里，写回时两段结果要按 router 给出的门控权重加权求和后才能落到该 token 的最终输出上。若把加权放在写回 kernel 里做，就省掉一次单独的 combine pass；若分开做，则多一次 $M_{total}\\times N$ 的读写往返。这个选择直接决定了解码路径上每层的端到端时延。</p>\n\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-12\">十二 · 资源释放与进入下一层的衔接</h3>\n<p>最后一步是释放 TMEM 与共享内存，把控制权交回给下一层。输入是本层已完成的全部段结果，输出是干净的 TMEM 分区与可复用的共享内存槽位。这一步看似无计算，实则是流水线衔接的关键：MoE 层之后通常紧跟残差、归一化或下一层的 attention，若释放与下一层的预取不能重叠，层与层之间会出现同步点，把单 kernel 融合在层内省下的气泡在层间又还回去。</p>\n<p>代价体现在占用率与功耗两侧。TMEM 是有限资源，若分段累加器占满了全部分区，下一层的 MMA 就无法提前启动，只能等释放完成，形成层间串行。共享内存同理，偏移表与 A 的 staging buffer 若一直占着，后续算子拿不到空间。功耗侧则是张量核心在段边界与层边界上的空转，利用率曲线上的凹陷直接对应能效下降——空转的 SM 仍在漏电。</p>\n<p>具体例子：一个 64 专家的 MoE 层，若每段都申请独立的 TMEM 分区而不复用，TMEM 很快耗尽，后续层的 MMA 被迫等待；正确做法是让所有段共享同一组累加器分区、按段清零复用，把 TMEM 占用压到与专家数无关的常量。这正是“偏移表随专家数线性增长、但 TMEM 占用不随专家数增长”这一工程判断的由来：可扩展性的瓶颈在元数据与共享内存，而不在累加器。</p>\n<p>把五步串起来看，单 kernel 覆盖全部专家的收益来自第一步到第五步之间没有任何 kernel launch 边界，代价则集中在三处：拼接 A 的 gather 带宽、段边界的指针切换与 TMEM 清零气泡、以及倾斜分布下的 tile 尾部浪费。三者中前两者可靠工程手段压缩，第三者只能靠路由侧的容量控制或块稀疏手段缓解——分组 GEMM 本身对分布不均是无能为力的，它只是把分布的真实形状诚实地映射到了 Util 上。</p>\n\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-13\">十三 · 段边界如何吃掉收益：偏移表、尾部空转与段间气泡</h3>\n<p>把各专家的 token 块拼成统一 A 矩阵后，真正的执行语义是分段矩阵乘 <span class=\"formula\">$$Y[m_s:m_{s+1},:]=A[m_s:m_{s+1},:]\\cdot B_s$$</span>，其中 $m_s$ 是第 $s$ 个专家段的起止偏移，$B_s$ 是该专家权重，累加器驻留 TMEM。这条公式暴露了方案的边界：收益来自一次 launch 覆盖全部专家，代价则全部压在 $m_s$ 的分布形状上。当 router 把 token 高度倾斜地分配给少数专家时，拼接矩阵的每一段长度差异极大，而 tcgen05 的 MMA 以固定 tile_M 推进，短段末尾必然留下无法被任何专家填充的空 tile。此时利用率由 <span class=\"formula\">$$\\text{Util}=\\frac{\\sum_e M_e}{E\\cdot\\lceil \\max_e M_e/\\text{tile}_M\\rceil\\cdot \\text{tile}_M}$$</span> 决定——分母按最大专家段对齐，分子是真实 token 总量，两者差距就是尾部浪费。工程判断很直接：只要 $\\max_e M_e$ 显著高于均值，Util 就会跌破 50%，此时 2-SM 协作再强也只是把空转摊到两个 SM 上，GEMM 吞吐随 Util 线性下滑，单层时延的 SLO 直接失守。</p>\n<p>第二类失效来自段元数据本身。偏移表要为每个专家保存起止偏移、长度与 B 权重指针，这些量随专家数线性增长，占用寄存器与共享内存；当专家数增多，段表膨胀会压低 occupancy，使原本用于隐藏 TMEM 访存延迟的 warp 数不足。更隐蔽的是段间切换：tcgen05 MMA 在每段开始前要切换 B 权重指针并对 TMEM 累加器分段清零，若清零与下一段 MMA 的发射没有重叠，段与段之间就插入气泡，单 kernel 融合省下的 CPU 启动开销被这些气泡逐段抵消。专家数越多、每段越短，气泡占比越高，融合收益越接近零。</p>\n<p>因此这套机制有明确的适用边界：专家数多、单专家 token 块偏小且分布相对均匀的 MoE 层最受益；一旦分布长尾明显或专家数推到共享内存与寄存器约束的上限，就应退回按专家分簇的多次 launch，或引入 token 重排与容量因子截断来压平 $m_s$ 分布。量化侧可叠加 NVFP4/FP8 权重以缩小 B 段切换的带宽代价，但这不改变尾部空转的结构性损失。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>直接代价</th><th>工程对策</th></tr></thead><tbody><tr><td>专家 token 分布长尾</td><td>tile 尾部空转，Util 跌破 50%，单层时延上升</td><td>容量因子截断、token 重排压平段长</td></tr><tr><td>专家数增大</td><td>偏移表膨胀，寄存器/共享内存压力线性上升，occupancy 下降</td><td>段表下沉到共享内存、限制单 kernel 专家数</td></tr><tr><td>段间指针切换与 TMEM 清零未重叠</td><td>段间气泡，抵消单 kernel 融合收益</td><td>清零与下一段 MMA 发射流水化</td></tr></tbody></table>\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-14\">十四 · 分段矩阵乘公式：逐项拆解与偏移语义</h3>\n<p>核心公式写成 $$Y[m_s:m_{s+1},:]=A[m_s:m_{s+1},:]\\cdot B_s$$，它的信息量全部藏在索引约定里。$A$ 是拼接后的统一激活矩阵，形状 $M_{total}\\times K$，行方向按专家顺序排列，第 $s$ 个专家占据半开区间 $[m_s,m_{s+1})$，长度 $M_s=m_{s+1}-m_s$。$B_s$ 是第 $s$ 个专家的权重矩阵 $K\\times N_s$，注意 $N_s$ 允许逐专家不同——这正是 MoE 与稠密 GEMM 的本质区别，输出列宽不是全局常量。$Y$ 的行索引与 $A$ 完全对齐，因此写回时不需要任何行重排：第 $s$ 段的输出行天然对应第 $s$ 段输入的 token。累加器驻留 TMEM，意味着 $Y$ 的分段结果不是逐段落到 HBM 再拼，而是在张量核心侧完成累加后按段导出。</p>\n<p>推导的关键一步是把逐专家求和改写为单一大矩阵乘的分段视图。逐专家形式是 $Y_e=A_e B_e$，$e=1\\dots E$，每个 $A_e$ 形状 $M_e\\times K$。把 $A_e$ 沿行方向堆叠得到 $A=\\text{concat}(A_1,\\dots,A_E)$，则对任意 $s$ 有 $Y[m_s:m_{s+1},:]=A[m_s:m_{s+1},:]\\cdot B_s$。这一步成立的唯一前提是行堆叠保持专家内 token 的相对顺序不变——顺序无关紧要，因为输出行与输入行同索引，但段边界必须精确。于是问题从“$E$ 次独立 launch”变成“一次 launch 内的 $E$ 段循环”，$E$ 只影响控制流，不影响 kernel 数量。</p>\n<p>工程代价立刻显现：偏移表 $m_0\\dots m_E$ 需要 $E+1$ 个整数，若每个专家还带 $N_s$ 与权重指针，元数据规模随 $E$ 线性增长。这些量必须常驻寄存器或共享内存才能被 MMA 循环快速读取，因此专家数上升会直接压缩可用于流水线的寄存器预算，占用率下降是必然的连锁反应。举例：一个 $E=64$ 的 MoE 层，若每段元数据占 16 字节，偏移表约 1 KB，看似不大，但它要在每个 tile 迭代中被索引，放进共享内存会与 A/B 的 stage buffer 争抢容量。</p>\n\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-15\">十五 · 利用率公式：tile 尾部浪费的定量来源</h3>\n<p>$$\\text{Util}=\\frac{\\sum_e M_e}{E\\cdot\\lceil \\max_e M_e/\\text{tile}_M\\rceil\\cdot \\text{tile}_M},\\quad \\text{GEMM 吞吐}\\propto \\text{Util}\\cdot\\text{TC 峰值}$$ 分子是真实 token 总数，分母是按“最忙专家”统一分配 tile 数后的总 tile 容量。这个公式刻意用了 $\\max_e M_e$ 而非各专家实际所需 tile 数之和，因为分段执行时 tile 调度器往往按统一网格推进：每段都要向上取整到 $\\text{tile}_M$ 的整数倍，尾部不足一个 tile 的部分照样占用张量核心周期，只是有效行数不足。</p>\n<p>推导的关键一步是把“每段独立取整”的损失写成比值。设第 $e$ 段占用 $\\lceil M_e/\\text{tile}_M\\rceil$ 个 tile，则总容量为 $\\text{tile}_M\\sum_e\\lceil M_e/\\text{tile}_M\\rceil$，Util 即分子除以该容量。公式中把求和项替换为 $E\\cdot\\lceil\\max_e M_e/\\text{tile}_M\\rceil$，是在刻画最坏情形：当调度器为所有段预留与最忙段相同的 tile 数时，短段浪费被放大到极致。真实实现介于两者之间，但公式给出的下界足以做容量判断——只要专家分布长尾，Util 就会显著低于 1。</p>\n<p>具体例子：$\\text{tile}_M=128$，某层 $E=8$，各专家 token 数为 $900,700,500,300,200,120,60,20$。逐段取整后 tile 数为 $8,6,4,3,2,1,1,1$，总容量 $128\\times26=3328$，而 $\\sum M_e=2800$，Util 约 0.84；若调度器按 $\\max=900$ 统一预留 8 个 tile 给每段，容量膨胀到 $128\\times64=8192$，Util 跌到 0.34。这就是“Util 可能低于 50%”的算术来源，不需要任何实测。吞吐与 Util 成正比，意味着后一种调度下张量核心有一大半周期在空转，而功耗并不会同比例下降——空转 tile 仍在推进流水线。</p>\n\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-16\">十六 · 2-SM 协作对 M 维的补偿：为什么小段仍能打满</h3>\n<p>tcgen05 的 2-SM 协作模式让一对 SM 共同承担一次 MMA，把可用张量核心资源翻倍，代价是单次 MMA 的 M 维下限被抬高——协作本身要求足够的工作量摊薄同步开销。对 MoE 而言这恰好是解药：单专家 $M_e$ 常常只有几十到几百行，单 SM 下 M 维不足以填满 MMA 流水，而 2-SM 模式下即使 $M_e$ 偏小，两个 SM 的 tile 也能拼出可观的等效 M 维，把 $\\text{Util}\\cdot\\text{TC 峰值}$ 中的 TC 峰值项真正兑现。</p>\n<p>代价要算清楚：2-SM 协作意味着每个专家段占用两个 SM 的资源，段间切换时两个 SM 必须同步——B 权重指针切换与 TMEM 累加器分段清零若不在同一屏障上完成，一个 SM 提前进入下一段就会与伙伴错位，段间插入气泡。伪代码层面这体现为段循环内的显式同步点：</p>\n<ul>\n<li>读偏移表取 $[m_s,m_{s+1})$ 与 $B_s$ 指针，广播到协作的两个 SM；</li>\n<li>按 $\\text{tile}_M$ 切分该段，TMEM 累加器清零仅针对本段有效 tile；</li>\n<li>循环发起 MMA，A 的行偏移随 tile 推进，B 指针在本段内固定；</li>\n<li>段末屏障：两 SM 确认累加完成，按行偏移把 TMEM 结果写回 $Y$ 的对应区间；</li>\n<li>推进 $s$，重复直至 $E$ 段耗尽，最后统一释放 TMEM 与共享内存。</li>\n</ul>\n<p>这里“分段清零”而非“整块清零”是性能关键：若每段都清空整个 TMEM 累加器，清零带宽随 $E$ 线性叠加，小段场景下清零开销可能超过 MMA 本身。只清本段实际占用的 tile 行，把无效行留给下一次覆盖写，是可行的工程折中。显存侧，TMEM 是片上资源，分段驻留不增加 HBM 流量，但段间写回的 $Y$ 分片会形成不规则的写模式，写回粒度若小于 cache line 会浪费带宽。</p>\n\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-17\">十七 · 伪代码落到可实现：偏移表与段循环的数据结构</h3>\n<p>把上面的循环写成可编译的形态，需要三个结构：偏移数组、段描述符、以及按段推进的 tile 迭代器。偏移数组 $m[0\\dots E]$ 单调不减，段描述符至少含 $\\{m_s, m_{s+1}, B_s\\text{ 指针}, N_s\\}$。伪代码思路如下，重点在索引算术而非语法：</p>\n<div class=\"formula\">$$ \\begin{aligned} &amp;\\textbf{for } s \\leftarrow 0 \\textbf{ to } E-1:\\\\ &amp;\\quad \\text{off} \\leftarrow m[s];\\ \\ \\text{len} \\leftarrow m[s+1]-m[s];\\\\ &amp;\\quad \\text{tiles} \\leftarrow \\lceil \\text{len}/\\text{tile}_M\\rceil;\\\\ &amp;\\quad \\textbf{for } t \\leftarrow 0 \\textbf{ to } \\text{tiles}-1:\\\\ &amp;\\quad\\quad \\text{rows} \\leftarrow \\min(\\text{tile}_M,\\ \\text{len}-t\\cdot\\text{tile}_M);\\\\ &amp;\\quad\\quad \\text{MMA}(A[\\text{off}+t\\cdot\\text{tile}_M : +\\text{rows}],\\ B_s,\\ \\text{TMEM}[t])\\\\ &amp;\\quad \\text{writeback}(Y[\\text{off}: \\text{off}+\\text{len}],\\ \\text{TMEM}[0:\\text{tiles}])\\\\ &amp;\\quad \\text{barrier}() \\end{aligned} $$</div>\n<p>可实现性取决于两个细节。第一，$\\text{rows}$ 小于 $\\text{tile}_M$ 时 MMA 的 M 维是变量，tcgen05 的指令形态要求 M 维落在允许的离散档位上，因此尾部 tile 通常要向上取整到最近档位并在写回时裁掉多余行——这就是 Util 公式里取整损失的物理来源。第二，TMEM 分段索引 $\\text{TMEM}[t]$ 必须与写回时的行区间严格对应，段内 tile 序号从 0 重新计数，否则跨段累加会污染结果。寄存器压力来自 $\\text{off}$、$\\text{len}$、$\\text{tiles}$ 与 $B_s$ 指针在段循环中的活跃性，专家数增大时段循环迭代次数上升，但这些量本身不随 $E$ 增长——真正线性增长的是偏移数组的存储，它应放在共享内存或常量区，避免占用寄存器。</p>\n<p>延迟代价可以定性拆解：单 kernel 消除了 $E$ 次 launch 的 CPU 侧开销与流水线气泡，但引入了段间屏障，每次屏障的代价与 2-SM 同步延迟同阶。当 $E$ 大而每段极短时，屏障次数逼近 $E$，融合收益被同步开销侵蚀——这正是失败模式中“段间气泡抵消融合收益”的机制。判断准则很直接：若单段 MMA 的有效周期数小于屏障开销，就该考虑把多个小专家合并到同一段内处理，用 $N_s$ 拼接换取更少的段切换。</p>\n\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-18\">十八 · 量化叠加下的公式变形：$K$ 维与缩放因子的位置</h3>\n<p>当权重与激活走 NVFP4/FP8 微缩放量化时，分段公式的 $K$ 维被切分为量化块，$B_s$ 不再是一个稠密矩阵而是“块缩放因子 + 低精度元素”的组合。公式形式上仍是 $Y$ 段等于 $A$ 段乘 $B_s$，但累加在 TMEM 中按块进行，缩放因子在块边界处乘入。推导的关键一步是把缩放提到累加之外：若同一 $K$ 块内缩放因子恒定，则该块的贡献可写成 $(\\text{块内点积})\\times\\text{scale}$，于是 TMEM 累加器可以保持高精度累加、只在块末做一次缩放乘加，避免每元素一次乘法。</p>\n<p>代价落在带宽与精度两侧。低精度权重把 $B_s$ 的字节数压到 FP16 的数分之一，HBM 读带宽压力显著下降，但缩放因子本身要随权重一起搬入共享内存，块越小因子开销占比越高。分段切换 $B_s$ 指针时，指针现在指向“元素区 + 因子区”两段地址，段描述符需要多一个字段，偏移表之外再添一层元数据，寄存器与共享内存压力在专家数之外又多了一个随块数增长的维度。具体例子：$K=4096$、块大小 16，则每专家权重带 256 个缩放因子；$E=64$ 时因子总量 16384 个，若以 FP8 存储约 16 KB，与 A/B 的 stage buffer 同处共享内存时需重新分配容量。</p>\n<p>稳定性上，分段清零与缩放乘加的次序不能颠倒：若先乘缩放再清零，段间残留的缩放状态会污染下一段首块。工程判断是让缩放乘加成为写回路径的一部分，与 TMEM 导出绑定，而不是留在累加循环里——这样段间屏障只需保证累加完成，缩放状态天然随段重置。</p>\n\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-19\">十九 · 从公式到容量判断：三个可计算的量</h3>\n<p>公式的实用价值在于把三个量变成可估算的输入。其一是 Util 下界：给定 $\\text{tile}_M$ 与专家 token 分布，用 $\\sum_e M_e$ 除以 $E\\cdot\\lceil\\max_e M_e/\\text{tile}_M\\rceil\\cdot\\text{tile}_M$ 得到最坏利用率，若该值低于可接受阈值，说明拼接矩阵的 tile 尾部空转已成主要瓶颈，此时增大 $\\text{tile}_M$ 会恶化而非改善——因为取整损失随 tile 变大而放大。其二是段切换次数：$E$ 直接决定屏障次数，屏障开销与单段 MMA 周期数之比决定融合是否划算。其三是元数据占用：偏移表与段描述符的字节数乘以 $E$，与共享内存中 A/B stage buffer 的容量做减法，得到实际可用流水深度。</p>\n<p>三个量共同指向一个工程判断：分组 GEMM 的收益不是无条件的，它把逐专家 launch 的 CPU 开销换成了段间同步与 tile 取整损失，前者随 $E$ 增长而后者随专家分布不均而增长。当专家分布接近均匀且 $E$ 适中时，Util 接近 1，单 kernel 融合净赚；当分布长尾且 $E$ 很大时，Util 跌破 50% 与屏障开销叠加，融合收益被吃掉。此时正确的动作不是放弃分组，而是调整分段粒度——把多个小专家拼进同一段共享一次屏障，用 $N_s$ 的列拼接替代行拼接，代价是 $B_s$ 指针在段内也要切换，回到段内多指针的复杂度。这个取舍点由上面三个量算出，而非凭经验拍板。</p>\n\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-20\">二十 · 分段矩阵乘的边界：Util 何时塌陷、偏移表何时压垮占用率</h3>\n<p>把逐专家 launch 折叠成单 kernel 的收益全部来自一个前提：拼接后的统一 A 矩阵在 M 维上足够“厚”。核心恒等式是分段矩阵乘 <span class=\"formula\">$$Y[m_s:m_{s+1},:]=A[m_s:m_{s+1},:]\\cdot B_s$$</span>，其中 <span class=\"formula\">$$m_s$$</span> 是第 s 个专家 token 段的起止偏移，<span class=\"formula\">$$B_s$$</span> 为该专家权重，累加器常驻 TMEM 并按段清零。推导的关键一步在于：tcgen05 的 MMA 以 tile 为粒度推进，段长 <span class=\"formula\">$$M_e=m_{s+1}-m_s$$</span> 若不能被 <span class=\"formula\">$$\\text{tile}_M$$</span> 整除，该段最后一个 tile 只有部分行参与计算，其余行空转但仍占用张量核心周期。于是有效算力利用率退化为 <span class=\"formula\">$$\\text{Util}=\\frac{\\sum_e M_e}{E\\cdot\\lceil \\max_e M_e/\\text{tile}_M\\rceil\\cdot \\text{tile}_M}$$</span>，而 GEMM 吞吐正比于 <span class=\"formula\">$$\\text{Util}\\cdot\\text{TC 峰值}$$</span>。注意分母用的是 <span class=\"formula\">$$\\max_e M_e$$</span> 而非均值：只要有一个专家段特别长，所有段都被拉齐到同一 tile 计数上评估，尾部浪费被放大。</p>\n<p>这个公式直接给出失效条件。当 router 分布接近均匀时，各段长度相近，分母接近 <span class=\"formula\">$$\\sum_e M_e$$</span> 的向上取整，Util 接近 1；一旦出现“热专家 + 长尾专家”的偏斜分布，短段被迫按长段的 tile 数计费，Util 跌破 50% 是结构性的而非偶发。此时单 kernel 融合省下的 launch 开销，抵不过张量核心空转的损失，方案反而劣于按段拆分。工程上的判断是：先看 batch 内 router 直方图的 <span class=\"formula\">$$\\max_e M_e/\\text{mean}_e M_e$$</span> 比值，再决定是否启用拼接路径。</p>\n<p>第二个边界来自偏移表本身。每段需维护起止偏移、B 权重指针、TMEM 累加器基址，这些元数据随专家数 E 线性增长，直接吃寄存器与共享内存预算；占用率一旦因寄存器压力下降，2-SM 协作模式补偿小 M 维的能力也被削弱。下表对比两种路径在偏斜分布下的代价取向：</p>\n<table class=\"mini\"><thead><tr><th>路径</th><th>启动开销</th><th>tile 尾部浪费</th><th>元数据压力</th></tr></thead><tbody><tr><td>逐专家 launch</td><td>随 E 线性上升，含流水线气泡</td><td>仅单段内浪费</td><td>可忽略</td></tr><tr><td>单 kernel 分段拼接</td><td>一次 launch</td><td>按 <span class=\"formula\">$$\\max_e M_e$$</span> 拉齐，偏斜时显著</td><td>随 E 线性上升</td></tr></tbody></table>\n<p>最后是段间气泡：切换 <span class=\"formula\">$$B_s$$</span> 指针与 TMEM 分段清零若未与上一段的写回重叠，每个段边界都会插入一段同步等待，E 越大累计越可观，足以抵消融合收益。可实现的伪代码思路是把“写回段 s 结果”与“预取段 s+1 的 B 指针、清零下一块 TMEM 分区”放在同一流水阶段，用双缓冲 TMEM 分区隐藏切换延迟；NVFP4/FP8 权重量化可进一步压低 B 段加载带宽，但量化本身不改变 Util 的分子分母结构，偏斜分布的尾部浪费依旧存在。</p>\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-21\">二十一 · 请求形态的匹配：批内多专家并发是前提</h3>\n<p>分组 GEMM 的收益来自“一次 launch 覆盖全部专家”，而这个前提只有在单层内确实存在多专家并发时才成立。负载配方的第一维就是请求形态：同一 batch 内的 token 经 router 分配后，必须同时落在足够多的专家上，拼接后的 $M_{total}$ 才有意义。若一个 batch 的 token 高度集中于少数专家（例如领域高度同质的短请求、或 router 在低负载下塌缩到热门专家），拼接矩阵的段数少、段间长度悬殊，kernel 退化为“少数大段 + 大量空段”，2-SM 协作与 TMEM 分段累加带来的补偿效应被浪费。此时更合适的形态是逐专家 launch 或按专家聚类的批调度，而不是强行拼接。</p>\n<p>工程上判断请求形态是否匹配，看的是 router 输出的段长分布而非平均段长。设第 $e$ 个专家收到 $M_e$ 个 token，段长向量 $\\{M_e\\}$ 的离散程度直接决定 tile 尾部浪费：</p>\n<div class=\"formula\">$$\\text{Util}=\\frac{\\sum_e M_e}{E\\cdot\\lceil \\max_e M_e/\\text{tile}_M\\rceil\\cdot \\text{tile}_M},\\quad \\text{GEMM 吞吐}\\propto \\text{Util}\\cdot\\text{TC 峰值}$$</div>\n<p>分母按最大段对齐，意味着只要有一个专家段特别长，所有段的 tile 数都被拉到同一量级，短段尾部空转。举例：8 个专家、tile_M 取 128，段长为 [512, 384, 256, 128, 64, 32, 16, 8]，$\\max_e M_e=512$ 对应 4 个 tile，分母为 $8\\times4\\times128=4096$，分子为 1400，Util 仅约 34%。同样总量若均匀分布为每段 175，Util 可接近 100%。这就是“请求形态匹配”的量化含义：不是看总 token 数，而是看最大段与平均段之比。</p>\n\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-22\">二十二 · 长度分布：解码与预填的段长结构差异</h3>\n<p>长度分布对分组 GEMM 的影响体现在两个层面。其一是单请求内的序列长度：预填阶段每个请求贡献大量 token，单请求就可能填满一个专家段，段长分布相对平滑；解码阶段每请求每步只贡献一个 token，段长由“该步路由到该专家的请求数”决定，天然带有泊松式波动，短段占比高。其二是 batch 内请求长度的混合：长请求与短请求混批时，预填 token 集中在少数请求上，router 分配更容易出现尖峰段。</p>\n<p>因此负载配方要求按阶段区分 tile 策略。解码侧应把 tile_M 调小、更多依赖 2-SM 协作把小 M 维拼成可用的 MMA 形状；预填侧则可放宽 tile_M、让长段连续占用 TMEM 以减少分段清零次数。伪代码层面的判断是：</p>\n<ul>\n<li>若 $\\max_e M_e / \\text{tile}_M$ 远大于 $\\sum_e M_e/(E\\cdot\\text{tile}_M)$，说明分布尖峰，优先考虑容量因子路由或按专家重排 batch；</li>\n<li>若多数 $M_e &lt; \\text{tile}_M$，说明段过短，应启用 2-SM 协作并考虑合并相邻小段（在权重指针切换允许的前提下）；</li>\n<li>若 $M_e$ 的方差随 batch 增大而收敛，说明批大小已进入分组 GEMM 的甜区。</li>\n</ul>\n<p>代价方面，长度分布不均直接转化为张量核心空转：tile 尾部空转不产生有用 FLOPs，但 TMEM 占用与共享内存带宽照常消耗，等于用同样的功耗买更少的有效计算。对 SLO 关注单层 GEMM 时延的场景，尖峰段还会拉长关键路径——最长的那个专家段决定整层完成时间，短段提前完成后其 SM 只能空等或提前释放，形成流水线气泡。</p>\n\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-23\">二十三 · 并发与批大小：甜区与两侧的退化</h3>\n<p>批大小决定 $M_{total}$，也决定段长分布的统计稳定性。批太小，$M_{total}$ 不足以让每个专家段达到一个 tile，拼接的意义退化为“把多个不足一 tile 的小段塞进同一个 kernel”，此时 2-SM 协作是唯一能打满张量核心的手段，但段间切换 B 权重指针与 TMEM 清零的开销占比上升，单 kernel 融合的收益被段间气泡抵消。批太大，段长分布趋于均匀、Util 上升，但偏移表与段元数据随专家数线性膨胀，寄存器与共享内存压力增大，可能触发占用率下降，反而压低每 SM 的常驻 warp 数。</p>\n<p>甜区的判据可以写成对“每段至少一个 tile”的检查：当 $M_{total}/E \\gtrsim \\text{tile}_M$ 时，均匀分布下每段都能填满至少一个 tile，Util 接近上限；当 $M_{total}/E \\ll \\text{tile}_M$ 时，必须依赖 2-SM 把小段拼成 2-SM MMA 的有效 M 维，否则 tile 尾部浪费成为主导。并发维度还有一层：多请求并发时 router 的分配相关性。若并发请求来自同一领域，router 倾向同一批专家，段长分布反而更尖；若并发请求领域分散，段长分布更平滑。这解释了为什么同一 batch 大小在不同流量构成下表现差异明显——负载配方必须把“流量领域混合度”作为并发之外的独立变量。</p>\n<p>具体例子：一个在线服务在低峰期 batch 只有数十个 token，分组 GEMM 的段间切换开销占比高，此时应回退到逐专家 launch 或合并请求；高峰期 batch 达到数千 token，段长分布收敛，分组 GEMM 的 Util 与吞吐优势才显现。容量规划上，这意味着分组 GEMM 的吞吐曲线不是单调的，低负载区存在一个“融合不划算”的凹陷。</p>\n\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-24\">二十四 · 负载不对时的三种失败模式</h3>\n<p>第一种是分布极度不均导致的 tile 尾部空转。前面算过的 Util 低于 50% 的情形就是典型：最大段决定分母，短段全部陪跑。此时张量核心利用率跌破一半，而 TMEM 与共享内存仍按最大段配置，显存与带宽开销不降。缓解手段包括容量因子路由（把超出容量的 token 丢弃或溢出到次优专家，压平段长）与按专家重排 batch，但前者引入精度损失、后者引入重排延迟，都属于用系统代价换 Util。</p>\n<p>第二种是专家数增多导致的元数据膨胀。偏移表需要为每个专家保存起止偏移，段切换逻辑需要保存 B 权重指针，这些状态随 $E$ 线性增长，挤占寄存器与共享内存。占用率下降后，单 SM 可常驻的线程块减少，隐藏段间气泡的能力变弱，形成“专家越多、融合越不划算”的反直觉现象。规模上限受共享内存与寄存器约束，材料未给出具体专家数上限，工程上应以编译期资源报告为准做准入判断。</p>\n<p>第三种是段间同步不当引入气泡。分段切换 B 权重指针与 TMEM 累加器清零若没有与 MMA 流水重叠，每个段边界都会插入一次等待，段数越多气泡总量越大，抵消单 kernel 融合消除 launch 开销的收益。这要求偏移表驱动的段循环把“清零下一段累加器”与“写回上一段结果”做成流水，而不是串行执行。</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>触发条件</th><th>系统代价</th><th>缓解方向</th></tr></thead><tbody><tr><td>tile 尾部空转</td><td>段长方差大、最大段远高于均值</td><td>张量核心利用率跌破 50%，功耗换不到有效 FLOPs</td><td>容量因子路由、按专家重排 batch</td></tr><tr><td>元数据膨胀</td><td>专家数多、偏移表与段状态线性增长</td><td>寄存器/共享内存压力上升，占用率下降</td><td>压缩段元数据、限制单 kernel 专家数</td></tr><tr><td>段间气泡</td><td>B 指针切换与 TMEM 清零未流水化</td><td>段边界等待，抵消融合收益</td><td>清零与写回重叠、双缓冲累加器</td></tr></tbody></table>\n\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-25\">二十五 · 配方落地：把负载特征映射到 kernel 参数</h3>\n<p>负载配方的落地不是选一个固定 tile 大小，而是把可观测的负载特征映射到 kernel 参数与调度决策。可观测特征包括：单层 router 输出的段长直方图、batch 内领域混合度、当前并发请求数、预填/解码阶段标记。映射规则的核心是两条阈值判断——段长分布的变异系数是否超过门限、$M_{total}/E$ 是否低于 tile_M。前者决定是否启用容量因子或重排，后者决定 tile_M 与 2-SM 协作的开关。</p>\n<p>与量化叠加时，配方还要考虑 NVFP4/FP8 权重下的 tile 形状约束：低精度 MMA 的 tile 粒度与累加器布局不同，段长不足一个低精度 tile 时浪费比例更高，因此低精度路径对段长分布的要求比 FP16 更苛刻。这也是为什么同一负载在 FP8 下 Util 可能明显低于 BF16——不是精度本身的问题，而是 tile 粒度变粗后短段更容易被浪费。</p>\n<p>工程判断上，分组 GEMM 的负载配方应作为调度器的输出而非静态配置：调度器在每层 router 完成后读取段长直方图，决定本层走融合 kernel 还是逐专家路径，并把决策与 batch 重排、容量因子联动。这样做的代价是每层多一次轻量决策与可能的 host-device 同步，收益是避免在错误负载上强行融合导致的利用率塌陷。对于 SLO 关注单层时延的场景，决策延迟必须远小于单层 GEMM 时延，否则调度本身成为瓶颈。</p>\n<p>最后落到具体机制：偏移表是负载配方的执行载体，它把段长直方图翻译成段循环的起止地址；2-SM 协作是短段补偿手段，让 $M_e &lt; \\text{tile}_M$ 的专家仍能占用完整张量核心；TMEM 分段清零是段间隔离的保证，其流水化程度决定气泡大小。三者共同构成“负载匹配则 Util 高、负载错配则代价显性化”的因果链，配方设计的本质就是让这三者在给定流量构成下同时处于高效区间。</p>\n\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-26\">二十六 · 负载配方：什么请求形态喂得饱分组 GEMM</h3>\n<p>这套方案的甜点区是“专家数多、单专家 token 块偏小、且块大小彼此接近”的 MoE 层内批处理。判据不在总 batch，而在<b>专家间 token 数的离散度</b>。设第 e 个专家分到 M<sub>e</sub> 个 token，tile<sub>M</sub> 为 MMA 的 M 维分块，则张量核心利用率由下式给出：</p>\n<div class=\"formula\">$$\\text{Util}=\\frac{\\sum_e M_e}{E\\cdot\\lceil \\max_e M_e/\\text{tile}_M\\rceil\\cdot \\text{tile}_M},\\quad \\text{GEMM 吞吐}\\propto \\text{Util}\\cdot\\text{TC 峰值}$$</div>\n<p>分母的含义是：拼接后的统一 A 矩阵按专家顺序切段，每段都要向上取整到 tile 边界，段尾空转的 tile 照样占用 tcgen05 的 MMA 周期。因此 Util 由<b>最长的那一段</b>决定，而不是平均值——一个专家分到 4 倍于均值的 token，就能把整层利用率拖到 50% 以下。这解释了为什么长上下文、单请求解码、以及 router 塌缩到少数专家的负载不适合本方案：它们的 M<sub>e</sub> 分布是重尾的，拼接只是把浪费从“多次 launch”换成了“段尾空转”。反过来，prefill 阶段的大 batch、多请求并发、router 负载均衡良好（容量因子调得保守）的形态，各专家块尺寸接近，Util 才能贴近 1，2-SM 协作再把小 M 维的短板补上。</p>\n<p>并发与批大小的配方要按“每专家 token 数 ≥ 一个 tile<sub>M</sub>”来反推，而不是按 GPU 显存上限。工程上可写成一条准入判据：给定当前 batch 的 router 直方图，若 max<sub>e</sub> M<sub>e</sub> 与 min<sub>e</sub> M<sub>e</sub> 之比超过阈值（经验上以 2～3 为界），就应拆批、调高容量因子或退回逐专家路径，否则单 kernel 融合的收益会被段尾空转吃掉。这条判据的代价是调度器要多做一次直方图统计与排序，但它换掉的是整层 GEMM 的时延——在 SLO 关注单层 GEMM 时延的场景里，这个交换是划算的。批大小过小时（每专家不足一个 tile），2-SM 模式也救不回来，因为协作的两个 SM 分到的仍是同一段不足 tile 的 M 维。</p>\n<p>负载不对时的失效是连锁的。其一，段尾空转直接压低 Util，GEMM 吞吐按上式线性下滑，单层时延上升，连续批处理里这一层的排队会向后传导，把 decode 的 ITL 拉长。其二，专家数增多使偏移表与段元数据膨胀，寄存器与共享内存压力随专家数线性增长，占用率下降后 2-SM 协作的并发段数减少，进一步放大段间气泡。其三，分段切换 B 权重指针与 TMEM 累加器分段清零若同步不当，会在段间插入气泡，抵消单 kernel 融合消除 launch 开销的初衷——这正是“负载对了但实现没对齐”的典型失败。量化（NVFP4/FP8 权重）只改变单段 MMA 的吞吐，不改变 Util 的几何，所以它不能用来掩盖负载失配。</p>\n<table class=\"mini\"><thead><tr><th>请求形态</th><th>M<sub>e</sub> 分布</th><th>Util 预期</th><th>系统代价落点</th></tr></thead><tbody><tr><td>大 batch prefill，router 均衡</td><td>窄、各段 ≥ tile</td><td>接近 1</td><td>偏移表开销可忽略，收益在 launch 消除</td></tr><tr><td>中等并发 decode，容量因子偏大</td><td>中等离散</td><td>0.5～0.8</td><td>段尾空转，单层时延上升</td></tr><tr><td>长上下文单请求 / router 塌缩</td><td>重尾，max/min &gt; 3</td><td>可能低于 0.5</td><td>空转 + 元数据膨胀 + 段间气泡</td></tr></tbody></table>\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-27\">二十七 · 硬件档位：2-SM 协作的占用率边界</h3>\n<p>在 Blackwell 上部署分组 GEMM，第一件要定下来的不是并行度，而是每个专家段是否走 2-SM 协作模式。tcgen05 的 2-SM MMA 让一对 SM 共享一次矩阵乘的 K 维流水，把单 SM 无法打满的 M 维摊到两个 SM 的 tile 上。对 MoE 层来说这正好对上痛点：单专家 token 块往往只有几十到几百行，单 SM 的 tile_M 装不满，张量核心空转；两个 SM 协作后等效 M 维翻倍，尾部浪费被摊薄。代价是占用率：2-SM 模式要求成对的 SM 同时空闲，且 TMEM 分配以 CTA pair 为单位，一旦某个 SM 被其他 kernel 占住，这一对就整段空等。工程判断是：专家数多、单专家 M 维小的层走 2-SM；专家 token 块已经足够大（M 维接近或超过 tile_M 的整数倍）时退回单 SM 模式，换取更灵活的调度粒度。</p>\n<p>硬件档位还决定 TMEM 的预算分配。TMEM 是 tcgen05 累加器的驻留地，分段清零意味着同一块 TMEM 要在多个专家段之间复用。若为每个专家段预留独立累加器，TMEM 容量随专家数线性膨胀，直接压掉可并发的 CTA 数；若复用同一块，段间必须插入清零与写回，形成气泡。配置思路是：按 <em>每 SM 一对累加器缓冲</em> 设计，段切换时用异步写回掩盖清零延迟，而不是为每段新开 TMEM 区域。</p>\n<div class=\"formula\">$$\\text{Util}=\\frac{\\sum_e M_e}{E\\cdot\\lceil \\max_e M_e/\\text{tile}_M\\rceil\\cdot \\text{tile}_M},\\quad \\text{GEMM 吞吐}\\propto \\text{Util}\\cdot\\text{TC 峰值}$$</div>\n<p>这条式子给出了档位选择的量化依据：分母由最大专家段决定，说明拼接矩阵的有效高度被最热的那个专家拖住。把 tile_M 调小能提高 Util，但 tcgen05 的 MMA 指令对 tile 形状有下限，2-SM 模式下的 tile_M 下限更高。因此档位配置实际是在“Util 上限”与“指令合法性下限”之间取交点，而不是自由调参。</p>\n\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-28\">二十八 · 并行拓扑：专家段跨 SM 的切分与偏移表放置</h3>\n<p>拓扑上要回答两个问题：一个专家段跨几个 SM，以及偏移表放在哪一级存储。前者的答案是 2-SM 协作对：每个专家段绑定一对 SM，段内 K 维流水在两颗 SM 的 TMEM 间交替累加，段完成后由主 CTA 统一写回。后者的答案决定寄存器压力——偏移表若放寄存器，专家数增大时线性吃紧；若放共享内存，则每次段切换多一次 smem 读，但换来了占用率稳定。工程上推荐把偏移表拆成两级：段起止偏移放共享内存常量区（只读、广播友好），段内 tile 计数放寄存器，因为后者只与当前段相关，不随专家数增长。</p>\n<p>拓扑还要与量化方案对齐。NVFP4/FP8 权重下，B 矩阵的微缩放因子按块存放，段切换 B 指针时缩放因子指针必须同步切换，否则会出现“权重换了、scale 没换”的静默错误。配置思路是把 B 指针与 scale 指针打包成一个段描述符数组，与偏移表同址存放，段切换只做一次描述符读取。这样段间气泡被压到一次 smem 访问的量级。</p>\n<ul>\n<li>段描述符：{B_ptr, scale_ptr, m_start, m_len}，四字段定长，便于向量化读取。</li>\n<li>跨 SM 切分：专家段按 K 维对半切给两颗 SM，各自累加后归约，避免 M 维切分导致的尾部二次浪费。</li>\n<li>失败模式对应：分段切换 B 指针与 TMEM 清零若同步不当，会在段间插入气泡，抵消单 kernel 融合的收益——描述符打包正是为消除这类同步而设。</li>\n</ul>\n\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-29\">二十九 · 量化方案：NVFP4/FP8 与分段累加的数值对齐</h3>\n<p>量化与分组 GEMM 的耦合点在累加器精度。tcgen05 的 TMEM 累加器在 FP8 输入下通常以更高精度累加，段间清零意味着每个专家段的累加是独立的，不会跨段污染。NVFP4 权重的微缩放是块级（block-wise）的，一个专家段的 B 矩阵可能跨越多个缩放块，段内 MMA 需要在块边界处切换 scale。配置思路是让缩放块的粒度与 tile_K 对齐：若块大小整除 tile_K，段内无需额外同步；若不整除，则在 tile 边界插入 scale 重载，代价是一次 TMEM 读改写。</p>\n<p>量化方案的选择直接影响显存与带宽预算。NVFP4 把专家权重压到 4 bit，专家权重总量随专家数线性增长的显存压力被显著缓解，但代价是反量化逻辑进入 MMA 前的数据通路，对 2-SM 模式的流水提出更高要求。FP8 则在数值稳定性上更保守，适合对输出精度敏感的层。工程判断：专家数多、权重显存是瓶颈时选 NVFP4；单层输出直接进入残差或归一化、对量化误差敏感时选 FP8。两者都可与分段累加叠加，因为累加器精度不随输入格式降级。</p>\n<table class=\"mini\"><thead><tr><th>量化</th><th>显存收益</th><th>段内同步点</th><th>适用判断</th></tr></thead><tbody><tr><td>NVFP4</td><td>权重压至 4 bit，专家数增大时显存线性压力缓解</td><td>缩放块边界需重载 scale</td><td>权重显存受限、专家数多的层</td></tr><tr><td>FP8</td><td>权重 8 bit，收益小于 NVFP4</td><td>块粒度较粗，同步点更少</td><td>输出精度敏感、残差直连的层</td></tr></tbody></table>\n<p>注意量化不改变 Util 公式的结构：M 维的浪费依旧由专家 token 分布决定，量化只影响单次 MMA 的吞吐上限与显存占用。把量化当成“提高 TC 峰值利用率”的手段会误判瓶颈。</p>\n\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-30\">三十 · KV 策略：分组 GEMM 与分页 KV 的显存共存</h3>\n<p>MoE 层的分组 GEMM 与注意力层的分页 KV 共享同一块 HBM，配置时必须把两者的显存预算分开核算。分组 GEMM 的显存开销来自三部分：拼接后的 A 矩阵（M_total×K）、各专家 B 权重、以及偏移表与段描述符。A 矩阵是激活，随 batch 增长；B 权重是静态的，随专家数增长；偏移表是小对象但随专家数线性增长。KV 策略的选择——分页大小、是否量化 KV——决定了留给 A 矩阵与 B 权重的余量。</p>\n<p>配置思路是把 KV 的页大小与分组 GEMM 的 tile_M 解耦：KV 页大小服务于注意力 kernel 的访存连续性，tile_M 服务于 tcgen05 的 MMA 形状，两者不必对齐。真正需要对齐的是 KV 量化格式与分组 GEMM 的输入格式——若 KV 以 FP8 存储，解码阶段的激活进入 MoE 时已是 FP8，可直接喂给分组 GEMM，省掉一次格式转换；若 KV 是 BF16，则 MoE 入口需要一次量化，这段转换的延迟要计入单层时延预算。工程判断：端到端全 FP8 通路能省掉转换，但要求注意力输出与 MoE 输入格式一致，这在预填与解码混合的 batch 里需要按请求打标。</p>\n<p>显存代价的定性表述：专家数增大时，B 权重与偏移表同时线性增长，前者是大头，后者虽小但会挤占共享内存配额，间接压低可并发 CTA 数。KV 策略若选择更细的页粒度，页表开销上升，与偏移表争夺同一块元数据缓存。</p>\n\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-31\">三十一 · 调度参数：batch 组装与段顺序</h3>\n<p>调度参数里最关键的是段顺序。拼接矩阵按专家顺序排列，段的执行顺序决定 TMEM 复用的节奏。若按 token 数降序排列专家段，最热的段先执行，长段占据 TMEM 时间长，后续小段频繁切换，气泡集中在中后段；若按升序排列，小段快速过一遍，长段收尾，气泡被推到末尾但总切换次数不变。配置思路是：按 token 数降序排列，并让最热的段绑定 2-SM 协作对，用它的长流水掩盖后续小段的切换开销。</p>\n<p>batch 组装参数决定 M_total 的规模。连续批处理下，新请求不断进入，MoE 层的 batch 是动态的。若每步都重新收集 token 块并重建偏移表，偏移表的构建开销会进入关键路径。工程做法是把偏移表的构建与 router 的输出融合：router 算出每个 token 的专家归属时，顺带做一次原子累加得到各专家计数，前缀和得到段偏移，避免二次遍历。这段逻辑的代价是 router 后的一次小规模 scan，相对分组 GEMM 的 MMA 时间可忽略，但省掉了一次全 batch 遍历。</p>\n<ul>\n<li>段顺序：token 数降序，热段前置并绑 2-SM。</li>\n<li>偏移表构建：与 router 融合，原子计数 + 前缀和，避免二次遍历。</li>\n<li>调度粒度：以 MoE 层为调度单元，层内一次 launch 覆盖全部专家，层间不拆。</li>\n<li>失败模式对应：专家 token 数分布极度不均时，拼接矩阵的 tile 尾部大量空转，张量核心利用率可能跌破 50%——降序排列让这种空转集中在末尾少数段，便于用 2-SM 模式补偿。</li>\n</ul>\n\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-32\">三十二 · 可复现的配置思路：从约束到参数</h3>\n<p>把上述选择串成一条可复现的路径，顺序是：先定硬件档位，再定拓扑，再定量化，最后定调度。硬件档位由单专家 M 维与 tile_M 下限的关系决定：M 维小于 tile_M 时强制 2-SM，否则单 SM。拓扑由专家数与偏移表预算决定：专家数多则偏移表拆两级、描述符打包；专家数少则偏移表可整体放寄存器。量化由显存瓶颈与精度敏感度决定，NVFP4 优先，FP8 兜底。调度由 token 分布决定，降序排列加热段前置。</p>\n<p>这条路径的验证方式是看 Util 公式的分子分母比：若 Util 低于 50%，说明分母被最大专家段拖住，此时要么调小 tile_M（受指令下限约束），要么用 2-SM 模式把等效 tile 摊薄，要么在 router 侧做容量因子限制（该主题在其他片段展开，此处只作指路）。若 Util 高但端到端时延不降，瓶颈已不在 GEMM 而在段间同步或 KV 访存，应转向描述符打包与 KV 格式对齐。</p>\n<p>稳定性上要盯住两个信号：偏移表引起的寄存器压力是否触发占用率下降，以及段切换的同步是否在时间线上留下可见气泡。前者用编译期的寄存器报告核对，后者用段间时间戳采样。两者任一恶化，都说明配置已越过该层的规模上限——材料未给出具体专家数上限，工程上以占用率不降为界。</p>\n<p>最后落在具体机制上：分组 GEMM 的收益来自单 kernel 覆盖全部专家，而这份收益能否兑现，取决于段描述符是否把 B 指针、scale 指针、段偏移打包成一次读取，以及 2-SM 协作对是否被调度器稳定地成对分配。配置的全部工作，就是让这两个机制在给定硬件档位下不被占用率与同步气泡抵消。</p>\n\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-33\">三十三 · 配方边界：Util 跌破五成时该退到哪里</h3>\n<p>这套分组 GEMM 配方的适用前提是「专家多、单专家 token 块偏小」，一旦 router 把 token 高度倾斜到少数专家，拼接矩阵的 tile 尾部就会大量空转，公式 <span class=\"formula\">$$\\text{Util}=\\frac{\\sum_e M_e}{E\\cdot\\lceil \\max_e M_e/\\text{tile}_M\\rceil\\cdot \\text{tile}_M}$$</span> 的分子不变而分母被最大专家撑满，Util 跌破 50% 时 GEMM 吞吐随之腰斩——此时 2-SM 协作救不了尾部空转，它只补偿小 M 维打不满张量核心的问题，不补偿「有 tile 但没数据」。工程判断是：把 Util 作为运行时观测量而非事后指标，逐层采样各专家 $M_e$ 分布，当 $\\max_e M_e / \\text{mean}_e M_e$ 超过阈值就对该层退回逐专家 launch 或按专家分组的多 kernel 路径，用 CPU 启动开销换回 tile 密度。</p>\n<p>第二个失效条件是偏移表膨胀。每段需记录起止偏移、B 权重指针与 TMEM 累加器清零位置，元数据随专家数线性增长，寄存器与共享内存占用同步上升，占用率下降会直接压低并发 CTA 数，反过来又拉长段间切换的等待。配方上应把偏移表放在共享内存的固定小区域并限制单 CTA 承载的专家段数，专家数超过承载上限时按专家分簇拆成多个 kernel，而不是无限堆表。段间气泡同样致命：切换 B 指针与 TMEM 分段清零若与 MMA 流水不同步，每个专家段都会插入一次空转，专家数越多累计代价越大，需用双缓冲的段描述符让下一段的指针切换与当前段 MMA 重叠。</p>\n<table class=\"mini\"><thead><tr><th>档位</th><th>选择</th><th>代价落点</th></tr></thead><tbody><tr><td>硬件</td><td>Blackwell，tcgen05 2-SM 协作 + TMEM 累加器</td><td>小 M 维下打满张量核心，但要求成对 SM 同步</td></tr><tr><td>量化</td><td>NVFP4/FP8 权重叠加</td><td>权重带宽下降，段切换的指针粒度变粗</td></tr><tr><td>调度</td><td>按 Util 阈值在融合与逐专家间切换</td><td>切换本身引入分支与重 launch 开销</td></tr></tbody></table>\n<p>可复现的配置思路是：先固定 2-SM 协作与 TMEM 分段累加为默认路径，量化选 NVFP4 权重以压低 B 段读取带宽，KV 与批调度参数按单层 GEMM 时延的 SLO 反推——因为本方案关注的是层内时延而非端到端吞吐，batch 内 token 按 router 分配后应尽快进入拼接，避免在调度队列里等待而放大专家分布的不均。验证时逐层打印 Util 与段间气泡计数，Util 低于 50% 或气泡占比超过段执行时间的两成，即判定该层不适合融合路径，回退到逐专家 launch；专家数增长时同步观察占用率，占用率下降就拆簇。这套配方的稳定性不来自参数调优，而来自把失效条件做成可观测的运行时开关。</p>\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-34\">三十四 · 显存与带宽：拼接矩阵的驻留代价与分段流水的读带宽</h3>\n<p>分组 GEMM 把 $E$ 个专家的 token 块拼成 $M_{total}\\times K$ 的统一激活矩阵 $A$，这一步在显存上不是免费的。$A$ 本身要完整驻留（或至少按段可寻址），而每个专家的权重 $B_s$ 在段切换时被重新读入。系统代价的第一项是激活矩阵的容量：$M_{total}$ 等于本层被路由到所有专家的 token 总数，乘以 $K$ 与激活字节宽度（NVFP4 下每元素半字节加微缩放元数据，FP8 下 1 字节）。当 batch 与序列长度推高时，$A$ 的增长是线性的，而它必须与分页 KV、专家权重共存于同一 HBM 预算中——这部分共存策略在讲分页 KV 与专家权重共存的片段里已经展开，此处只强调一点：分组 GEMM 的 $A$ 是<em>瞬时</em>缓冲，它的峰值出现在层内 GEMM 执行的窗口里，因此容量规划要按“层内峰值”而非“稳态均值”来算，否则会在长上下文、大 batch 的预填阶段先撞墙。</p>\n<p>第二项是权重读带宽。分段执行意味着 $B_s$ 按专家顺序被依次读取，单次 launch 内所有权重被扫一遍，读带宽需求近似为 $\\sum_e |B_e|$ 除以该层 GEMM 的执行时间。这里的关键是权重不再有跨 batch 的复用窗口——逐专家 launch 时同一专家的权重可能在多个 micro-batch 间被反复命中 L2，而单 kernel 拼接后每个专家的权重在一次前向里只被读一次，L2 命中率反而取决于专家权重总量是否放得下。当专家数多、单专家权重矩阵偏小时，权重总量可能超出 L2，此时读带宽成为分段流水的主要瓶颈，表现为段间切换 B 指针时的等待，而不是 MMA 本身的算力受限。</p>\n<p>具体例子：一个专家数较多、单专家 token 块偏小的 MoE 层，在预填阶段 $M_{total}$ 很大但分布到每个专家的段长很短。此时 $A$ 的容量压力与权重扫读带宽压力同时上升，而 tile 利用率却因段短而下降——三种代价在同一窗口叠加，这是分组 GEMM 在预填侧最典型的显存-带宽夹击形态。</p>\n\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-35\">三十五 · 通信：单 kernel 融合对集合通信窗口的压缩</h3>\n<p>分组 GEMM 的通信代价不在 kernel 内部，而在它对外部通信窗口的挤压。MoE 层在专家并行下需要 all-to-all 把 token 分发到持有对应专家的 rank，再在 GEMM 后做反向 all-to-all 回收。逐专家 launch 时，每个专家的 GEMM 是一个独立的、可与通信重叠的小窗口；单 kernel 覆盖全部专家后，这个窗口被合并成一个大的、不可分割的执行段，通信只能在它之前或之后发生。系统代价是：<strong>重叠机会减少，通信暴露时间变长</strong>。在 NVLink 5 与 NIXL 支撑的分离式部署里，这意味着分组 GEMM 的执行时间必须被计入端到端关键路径，而不能像小 kernel 那样被通信“填缝”。</p>\n<p>更细的机制是段顺序与 all-to-all 到达顺序的对齐。拼接矩阵按专家顺序排列，若上游 all-to-all 按 rank 到达而非按专家到达，则 kernel 必须等最慢的 rank 把它的全部 token 段送齐才能启动，形成木桶效应。缓解手段是把分段边界做成可流式消费的：某专家的段一旦到齐即允许该段 MMA 启动，TMEM 累加器按段独立清零，不必等全局屏障。代价是偏移表要支持“部分就绪”状态，寄存器与共享内存的段元数据管理复杂度上升，这正是偏移表开销随专家数线性增长的另一面。</p>\n<p>量化到系统指标：通信暴露时间约等于 all-to-all 的最大 rank 延迟减去可与 GEMM 重叠的部分。单 kernel 融合把可重叠部分压到接近零，因此端到端时延对最慢 rank 的敏感度显著上升。工程判断是：在 NVLink 域内、rank 间负载均衡良好时，这一代价可接受；跨域或存在慢节点时，分组 GEMM 的单 kernel 形态会把通信抖动直接放大成层时延抖动。</p>\n\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-36\">三十六 · 功耗与占用率：偏移表的寄存器-共享内存税</h3>\n<p>偏移表是分组 GEMM 的元数据核心：每个专家段记录起止偏移与长度，供 MMA 切换 B 指针与 TMEM 分段清零使用。它的代价随专家数 $E$ 线性增长，落在寄存器与共享内存上。系统层面的后果是占用率（occupancy）下降：每个 SM 上驻留的偏移表项越多，可用于流水线缓冲与双缓冲的寄存器越少，tcgen05 的 2-SM 协作模式对共享内存的划分也越紧张。占用率下降直接压缩了延迟隐藏的空间——当段间切换 B 指针与 TMEM 清零的同步出现微小气泡时，没有足够的并发 warp 去填补，气泡就被暴露成真实时延。</p>\n<div class=\"formula\">$$\\text{Util}=\\frac{\\sum_e M_e}{E\\cdot\\lceil \\max_e M_e/\\text{tile}_M\\rceil\\cdot \\text{tile}_M},\\quad \\text{GEMM 吞吐}\\propto \\text{Util}\\cdot\\text{TC 峰值}$$</div>\n<p>上式给出的是算力侧的上界，但它没有计入占用率对有效 TC 峰值的折损。实际吞吐更接近 $\\text{Util}\\cdot\\text{TC 峰值}\\cdot f(\\text{occupancy})$，其中 $f$ 随偏移表规模单调下降。功耗侧的代价同样来自这里：分段切换是高频的控制流动作，B 指针切换与 TMEM 清零的同步若不能在编译期或硬件层面合并，会引入额外的指令发射与同步开销，在功耗预算紧张的 NVL72 机柜里表现为每层 GEMM 的能量效率下降，而不是峰值算力的下降。具体例子：专家数从数十增到上百时，偏移表项翻倍，共享内存中留给双缓冲的空间被挤压，段间气泡从可隐藏变为可见，Util 与 occupancy 同时下滑——这是规模上去后较早出现的一处崩塌点。</p>\n\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-37\">三十七 · 尾延迟：max_e M_e 决定的分段长度与 SLO 抖动</h3>\n<p>分组 GEMM 的尾延迟由最长的那一段决定，而不是平均值。公式里的 $\\lceil \\max_e M_e/\\text{tile}_M\\rceil$ 表明：tile 数量按最大专家段计算，所有专家共享同一 tile 粒度，于是 token 数少的专家段在尾部留下大量空转 tile。系统代价是双重的——算力上 Util 可能跌破 50%，时延上单层 GEMM 的完成时间被最热专家拉长。对 SLO 关注单层 GEMM 时延的场景，这意味着 p99 由路由分布的热点决定，而非由平均负载决定。</p>\n<p>尾延迟的传导路径是：最热专家段长 $\\max_e M_e$ 决定 kernel 的执行下界，其他段的空转 tile 不缩短这个下界，只浪费算力。当 batch 内路由分布随请求内容漂移时（例如某些请求集中触发同一批专家），$\\max_e M_e$ 会突然抬升，层时延出现尖峰。连续批处理下这种尖峰不会被子批稀释，因为分组 GEMM 是在整个 batch 的 token 集合上一次性拼接的。工程上的应对不是提高容量因子（那属于路由侧的话题），而是在分段边界上做更细的 tile 划分，让短段用更小的 tile_M，代价是 tile 数量增多、偏移表更复杂、控制流开销上升——又回到占用率与功耗的权衡。</p>\n<p>具体例子：一个 batch 内多数专家的段长只有几十个 token，而某一个专家因请求内容相关性收到数倍于均值的 token。此时 kernel 的执行时间由该专家段主导，其余专家的 tile 大量空转，Util 跌破 50%，而端到端 p99 相对 p50 的比值被这一层放大。这是分组 GEMM 在解码侧最需要监控的指标：不是平均 Util，而是 $\\max_e M_e / \\text{mean}_e M_e$ 的实时分布。</p>\n\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-38\">三十八 · 规模上去以后哪里先崩：三条曲线的交点</h3>\n<p>把上述代价按规模排序，崩塌顺序取决于三条曲线的斜率。第一条是偏移表开销随 $E$ 线性上升，挤压寄存器与共享内存，先表现为 occupancy 下降与段间气泡可见；第二条是 $\\max_e M_e$ 随路由集中度上升，先表现为 Util 下滑与尾延迟尖峰；第三条是权重扫读带宽随专家权重总量上升，先表现为段间 B 指针切换等待。在小规模（专家数少、路由均匀）时三条曲线都平缓，单 kernel 融合的收益（消除 launch 开销与流水线气泡）占主导。规模上去后，最先崩的通常是<strong>偏移表与占用率</strong>，因为它是线性且无上限的，而路由集中度与权重总量还受容量因子与量化宽度的调节。</p>\n<p>判断依据可以落到一个可观测的量：段间气泡占 kernel 执行时间的比例。当这个比例随专家数上升而单调增大时，说明偏移表开销已经越过占用率能吸收的阈值，此时继续增大单 kernel 覆盖的专家数不再划算，应考虑按专家分组拆成多个较小的 grouped kernel，用少量 launch 开销换回占用率。这与“单 kernel 覆盖全部专家”的初衷相反，但在规模上限处是必要的退让。材料未给出具体专家数上限，因此这个阈值必须在部署侧用实测的段间气泡比例来标定，而不是照搬固定数字。</p>\n<p>另一个先崩的点在分离式部署下是通信窗口：当分组 GEMM 的单 kernel 执行时间随 $M_{total}$ 增长而超过 all-to-all 的隐藏能力时，端到端时延对最慢 rank 的敏感度骤升，此时瓶颈从算力侧转移到通信侧。工程判断是：先看段间气泡比例判断算力侧是否已崩，再看通信暴露时间判断通信侧是否已崩，两者取先到者作为扩容或改拓扑的信号。功耗侧通常最后才成为硬约束，因为它是前两者的副产品——占用率下降与气泡增多都会推高每层 GEMM 的能量，但只有在机柜功耗预算触顶时才转化为部署限制。</p>\n\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-39\">三十九 · 规模上去以后，先崩的是利用率而不是算力</h3>\n<p>分组 GEMM 把全部专家压进一次 launch，收益来自消除逐专家启动开销，但这份收益随规模增长会被三处开销吃掉，且崩的顺序是确定的：先崩 tile 利用率，再崩片上存储占用，最后崩段间同步。利用率由分段长度分布决定：<div class=\"formula\">$$\\text{Util}=\\frac{\\sum_e M_e}{E\\cdot\\lceil \\max_e M_e/\\text{tile}_M\\rceil\\cdot \\text{tile}_M}$$</div>分母按最大专家段向上取整，意味着 router 只要把少数 token 集中到一两个专家，其余专家的段就全部落在同一块 tile 的尾部空转。tcgen05 的 2-SM 协作能把小 M 维下的张量核心填满，但它填的是“段内”，填不了“段尾”——2-SM 补偿的是 M 维不足，不是长度不均。因此规模上去后第一个失效条件不是专家数，而是分布偏斜度：Util 跌破 50% 时，GEMM 吞吐按 $\\text{Util}\\cdot\\text{TC 峰值}$ 等比塌陷，融合带来的启动开销节省完全无法对冲。</p>\n<p>第二处是片上存储。偏移表与段元数据随专家数线性增长，寄存器与共享内存占用同步上升，直接压低 occupancy；一旦 occupancy 掉档，TMEM 分段清零与 B 权重指针切换之间的延迟就无法被其他 warp 掩盖，段间气泡重新出现，单 kernel 融合的流水线优势被抵消。这里存在一个明确的工程拐点：专家数增加到偏移表挤占原本留给双缓冲共享内存的那一刻，kernel 从“算力受限”翻转为“元数据受限”，此时继续增大专家数只会让每段的有效 MMA 周期变短、切换周期变长。材料未给出具体专家数上限，但拐点的判据是可观测的——段切换开销占单段执行时间的比例开始随专家数单调上升。</p>\n<p>第三处是尾延迟与通信。分组 GEMM 的完成时间由最长专家段决定，而非平均段：单层时延的下界是 $\\max_e M_e$ 对应的 MMA 链，短段专家提前算完也只能等长段，SLO 关注单层 GEMM 时延时，偏斜分布直接把 p99 拉长到与均值脱钩。在分离式预填/解码与专家并行的拓扑下，这一层还叠加通信代价：专家权重按段切换指针，若专家分布在不同 rank 上，段边界就是集合通信边界，偏移表必须与 all-to-all 的到达顺序对齐，否则段间插入的是等待而非计算。功耗侧同样受偏斜支配——空转 tile 仍在供电，Util 低时每有效 FLOP 的能耗上升，能效比与利用率同向恶化。判断规模上限的方法因此不是看专家总数，而是看三件事同时发生：Util 逼近 50%、偏移表触发 occupancy 降档、最长段与平均段之比拉大——任一先到，就该退回逐专家 launch 或改用容量受限的专家放置策略，而不是继续加大单 kernel 覆盖面。</p>\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-40\">四十 · 精度漂移：分段累加与量化叠加的失配</h3>\n<p>分组 GEMM 在 tcgen05 上的精度问题不是「算错了」，而是「每段算得不一样」。TMEM 累加器按专家分段清零，意味着段与段之间没有跨段的数值连续性：第 s 段的结果只依赖本段 A 切片与 $B_s$，段边界处的舍入行为彼此独立。当 MoE 层叠加 NVFP4/FP8 权重时，问题被放大——每个专家的权重微缩放因子不同，段内累加顺序由 tile 划分决定，同一 token 若在不同 batch 中被路由到不同专家，其输出在低位上的偏差不可复现。诊断这类问题的关键是区分「量化误差」与「分段误差」：前者随 K 维增长呈随机游走，后者在段边界处呈阶跃。工程上可做的第一件事是给每个专家段单独记录累加器清零前后的 TMEM 快照校验值（对段输出做定点截断后求异或），一旦某段的校验值在相邻两次迭代中跳变超过阈值，即判定该段 B 指针切换或清零时序出错，而不是量化本身的问题。</p>\n<p>代价层面，精度诊断本身要花算力：逐段校验意味着每段多一次 TMEM 读回，读回带宽与 MMA 写回共享同一路径，在 Util 已经偏低的负载下会把单层 GEMM 时延进一步推高。因此校验应做成采样式——按专家 token 数加权抽样，只校验 token 数最多的前若干段，因为这些段贡献了绝大部分输出能量，也是尾部浪费最严重的地方。回滚策略上，精度异常不应直接退回逐专家 launch（那会丢掉 2-SM 协作的收益），而应先回滚量化档位：把 NVFP4 权重激活退回 FP8，保持分组 GEMM 结构不变，观察段校验值是否收敛；若仍跳变，再怀疑偏移表本身被写坏。</p>\n\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-41\">四十一 · OOM 的三条路径：TMEM、共享内存、偏移表</h3>\n<p>分组 GEMM 的显存失败很少是 HBM 不够，而是片上资源被段元数据吃掉。三条路径要分开看。第一条是 TMEM：tcgen05 的累加器驻留 TMEM，分段清零要求每段有独立的累加器视图，2-SM 协作模式下两个 SM 的 TMEM 分配必须对齐；当专家数增多、每段 M 维变小时，TMEM 的分配粒度反而变粗，出现「小段占大块」的碎片化，表现为可用 TMEM 容量下降而非耗尽。第二条是共享内存：偏移表、段长度、B 指针数组随专家数线性增长，与 A 矩阵的 stage 缓冲争抢同一块 SMEM，专家数翻倍时 SMEM 占用接近翻倍，直接压低 occupancy。第三条才是真正的 OOM——拼接后的统一 A 矩阵 $M_{total}\\times K$ 若一次性物化，在长上下文预填阶段会与分页 KV 抢 HBM。</p>\n<div class=\"formula\">$$\\text{SMEM}_{\\text{meta}} \\approx E\\cdot(c_{\\text{off}}+c_{\\text{len}}+c_{\\text{ptr}}),\\quad \\text{occupancy}\\propto \\frac{\\text{SMEM}_{\\text{total}}}{\\text{SMEM}_{\\text{meta}}+\\text{SMEM}_{\\text{stage}}}$$</div>\n<p>诊断顺序应是：先看 occupancy 是否随专家数单调下降（指向元数据膨胀），再看 TMEM 分配失败是否集中在专家数最多的层（指向碎片化），最后才查 HBM 水位。回滚手段对应三层：元数据侧把偏移表从 SMEM 搬到常量内存或由 host 侧预计算后以只读方式传入，牺牲一点访存延迟换 occupancy；TMEM 侧降低单段并行度，把 2-SM 协作退回单 SM 以换取更细的分配粒度；HBM 侧对 A 矩阵做分块物化，按专家段流式拼接而非全量驻留。每条回滚都有明确代价：常量内存方案增加段切换时的访存停顿，单 SM 方案牺牲小 M 维下的张量核心打满能力。</p>\n\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-42\">四十二 · 批抖动与路由不均：Util 的实时观测</h3>\n<p>批抖动指相邻 batch 之间专家 token 分布的剧烈变化，它让同一个 kernel 在不同迭代里跑出完全不同的 Util。路由不均则是单 batch 内的分布偏斜。两者叠加时，监控不能只看端到端吞吐，必须把 Util 拆到层、拆到段。可观测的最小单元是每段的 $M_e$ 与 tile 对齐后的有效 M：</p>\n<div class=\"formula\">$$\\text{Util}=\\frac{\\sum_e M_e}{E\\cdot\\lceil \\max_e M_e/\\text{tile}_M\\rceil\\cdot \\text{tile}_M},\\quad \\text{GEMM 吞吐}\\propto \\text{Util}\\cdot\\text{TC 峰值}$$</div>\n<p>注意分母用的是 $\\max_e M_e$ 而非各段之和——这正是分组 GEMM 的结构性代价：所有段共享同一个 tile 高度上界，最大的专家决定了整层的 tile 预算，小专家只能空转尾部。因此监控要同时上报 $\\max_e M_e/\\text{avg}_e M_e$ 这个偏斜比，偏斜比超过 tile 高度倍数时，Util 必然跌破 50%，此时吞吐瓶颈不在张量核心而在段划分。具体例子：某层路由后最大专家拿到接近一个 tile 高度的 token 数，而半数专家只有其零头，kernel 仍按最大段分配 tile，结果是大部分 tile 的有效行数不足一半，张量核心在等数据而非在算。</p>\n<p>诊断批抖动要区分「路由抖动」与「调度抖动」：前者是 router 输出的分布变化，后者是连续批处理把不同长度的请求拼进同一 batch 造成的 token 数波动。前者只能靠容量因子与丢弃策略吸收（该策略本身在别处展开），后者可通过固定 batch 内 token 预算、按专家分布做请求分组来平滑。尾延迟尖刺往往就来自这两者的共振：一个长预填请求把 batch 的 token 总量推高，路由分布随之偏移，最大专家段撑爆 tile 预算，单层 GEMM 时延出现尖峰。监控上应对每层记录 Util 的滑动分位数，尖刺定义为 P99 Util 相对 P50 的跌幅，而非绝对时延——因为绝对时延受 batch 大小影响，Util 跌幅才是结构信号。</p>\n\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-43\">四十三 · 段间气泡：指针切换与清零的同步窗口</h3>\n<p>单 kernel 融合的收益来自消除逐专家 launch 的 CPU 开销与流水线气泡，但融合本身会在段边界引入新的气泡：切换 B 权重指针、TMEM 分段清零、写回段输出，这三件事若不在同一流水级内重叠，段间就会出现张量核心空等。失败模式是同步不当——清零尚未完成就发起下一段 MMA，或指针切换的依赖链把 MMA 发射卡在等待上。诊断方法是给每段打时间戳，计算段间间隔与段内 MMA 持续时间的比值；比值显著大于零且随专家数增长，说明气泡随段数累积，融合收益被抵消。</p>\n<p>工程上的处理是把清零与写回做成异步：段 s 的结果写回由独立的写回 warp 承担，MMA warp 在清零段 s+1 的 TMEM 视图后立即发射，两者通过 TMEM 分区而非全屏障解耦。代价是 TMEM 需要同时容纳两段的累加器视图，占用翻倍，在专家数多、段 M 维小的场景下会与 OOM 路径一叠加。因此这是一个显式的权衡：要么接受段间气泡换 TMEM 余量，要么用双缓冲换吞吐但承担碎片化风险。回滚判断标准是气泡占比——若段间气泡已超过单层 GEMM 时延的可接受比例，说明融合在该负载下不成立，应退回更粗的段划分（合并小专家）而非退回逐专家 launch。</p>\n\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-44\">四十四 · 监控面与回滚阶梯</h3>\n<p>把上述失败模式收敛成一组可上报的指标，按层聚合：每段 $M_e$、偏斜比 $\\max_e M_e/\\text{avg}_e M_e$、Util、段间气泡占比、SMEM 元数据占用、TMEM 分配失败计数、段校验值跳变计数。这些指标的共同点是都能在 kernel 内部以极低开销采样，不需要额外 pass。监控的粒度选择本身是代价决策：逐段全采会拖慢 kernel，按专家 token 数加权采样能在覆盖主要输出的同时把开销压到可忽略。</p>\n<table class=\"mini\"><thead><tr><th>症状</th><th>首要怀疑</th><th>回滚动作</th><th>代价</th></tr></thead><tbody><tr><td>段校验值跳变</td><td>清零/指针切换时序</td><td>量化档位退回 FP8</td><td>精度换稳定，吞吐不变</td></tr><tr><td>occupancy 随专家数下降</td><td>偏移表膨胀</td><td>元数据搬出 SMEM</td><td>段切换访存停顿</td></tr><tr><td>TMEM 分配失败集中</td><td>分配碎片化</td><td>2-SM 退回单 SM</td><td>小 M 维打不满</td></tr><tr><td>Util P99 跌幅大</td><td>路由偏斜 + 批抖动</td><td>固定 token 预算、按分布分组</td><td>调度灵活性下降</td></tr><tr><td>段间气泡占比升</td><td>同步窗口不足</td><td>合并小专家、加粗段划分</td><td>段数减少、偏移表简化</td></tr></tbody></table>\n<p>回滚阶梯的原则是「先动数值、再动元数据、最后动并行拓扑」：数值回滚（量化档位）不改变 kernel 结构，风险最低；元数据回滚改变访存路径但不改变协作模式；并行拓扑回滚（2-SM 退单 SM）代价最大，因为它直接放弃 Blackwell 在小 M 维下打满张量核心的核心手段。每一级回滚都应绑定一个可观测的恢复判据——例如段校验值连续若干迭代无跳变、occupancy 回到基线、Util P99 跌幅收敛——而不是凭感觉切换。尾延迟尖刺的处理要单独成线：它往往是路由偏斜与调度抖动的共振，单靠 kernel 侧回滚无效，必须在 batch 组装阶段就把 token 预算与专家分布约束住，否则任何 kernel 级优化都只是在尖刺之间做平均。</p>\n\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-45\">四十五 · 段间气泡与占用率塌陷：分组 GEMM 的四类失效面</h3>\n<p>分组 GEMM 的收益全部押在“一次 launch 覆盖全部专家”上，因此它的失效也集中在这条流水线的接缝处。第一类是精度问题：分段切换 B 权重指针时，若某段的 TMEM 累加器未彻底清零，上一专家的部分和会渗入下一段，表现为个别专家输出系统性偏高；叠加 NVFP4/FP8 权重后，量化尺度按段独立，段边界处的缩放因子错配会把误差放大到可观测的 token 级偏差。诊断手段不是看整体 loss，而是按专家维度统计输出均值与方差，一旦某专家的输出分布相对同层其他专家出现稳定偏移，就应怀疑段边界清零或尺度绑定。第二类是 OOM：偏移表与段元数据随专家数线性增长，寄存器与共享内存压力同步上升，占用率下降后编译器可能被迫缩小 tile 或减少驻留 warp，反过来又压低 Util；显存侧的 OOM 常来自输出缓冲按 token 而非按段分配，拼接后的 A 矩阵与各段写回目标同时驻留，峰值显存等于两者之和而非最大值。</p>\n<p>第三类是批抖动与路由不均，二者同源。router 在 batch 内的分配决定了各段长度 $M_e$，而 tile 粒度固定，尾部浪费由下式直接给出：</p>\n<div class=\"formula\">$$\\text{Util}=\\frac{\\sum_e M_e}{E\\cdot\\lceil \\max_e M_e/\\text{tile}_M\\rceil\\cdot \\text{tile}_M},\\quad \\text{GEMM 吞吐}\\propto \\text{Util}\\cdot\\text{TC 峰值}$$</div>\n<p>分母按最大专家对齐，意味着一个热门专家就能拖垮整层利用率——专家 token 数分布极度不均时，拼接矩阵的 tile 尾部大量空转，张量核心利用率可能跌破 50%。此时 2-SM 协作只能补偿小 M 维打不满的问题，无法补偿空 tile。工程上应监控每层每专家的 $M_e$ 直方图与 Util 的滑动值，把 Util 低于阈值的层标记为“路由退化层”，而不是等端到端吞吐掉了才回头查。第四类是尾延迟尖刺：段间切换 B 指针与 TMEM 清零若同步不当，会在段与段之间插入气泡，专家数越多气泡累积越明显，单层 GEMM 时延的 P99 因此被拉长；这类尖刺在平均吞吐上看不见，只在 SLO 关注的单层时延上暴露。</p>\n<table class=\"mini\"><thead><tr><th>失效面</th><th>可观测信号</th><th>系统代价</th><th>回滚动作</th></tr></thead><tbody><tr><td>段边界精度</td><td>按专家输出均值偏移</td><td>token 级偏差，难定位</td><td>关闭分段清零复用，逐段独立累加</td></tr><tr><td>OOM / 占用率</td><td>偏移表尺寸、驻留 warp 数</td><td>显存峰值叠加、Util 下降</td><td>回退逐专家 launch 或缩小 tile</td></tr><tr><td>路由不均</td><td>每专家 $M_e$ 直方图、Util</td><td>空 tile 空转，吞吐跌破 50%</td><td>启用 capacity factor 截断热门专家</td></tr><tr><td>尾延迟尖刺</td><td>单层 GEMM P99</td><td>段间气泡累积</td><td>改回按专家分批 launch 平滑时延</td></tr></tbody></table>\n<p>回滚策略必须按失效面分级，而不是一刀切回旧路径。精度类问题优先在段边界加校验点：每段写回后抽样比对独立累加结果，确认无误再放开清零复用；路由不均优先调 capacity factor 与 token 丢弃策略，把 $\\max_e M_e$ 压到与均值同量级，Util 自然回升；只有偏移表膨胀到占用率不可接受、或段间气泡已无法通过同步原语消除时，才整体回退到逐专家 launch——那条路径的 CPU 启动开销与流水线气泡是已知代价，但它的时延曲线平滑、精度边界清晰，适合作为兜底档位。监控上应把 Util、每专家 $M_e$、单层 P99 三者绑定在同一张面板上，任何一项越界都触发对应的分级动作，而不是等端到端指标恶化后再做归因。</p>\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-46\">四十六 · 同族算法的坐标系：三种切分粒度</h3>\n<p>要谈“怎么选”，先要把同族算法摆到一个可比较的坐标系上。分组 GEMM 这一族在 MoE 推理里至少有三种切分粒度：<strong>逐专家 launch</strong>（每个专家一次独立 kernel）、<strong>普通 grouped GEMM</strong>（单 kernel、按专家分段但每段独占一个 CTA 的常规 MMA）、以及本卷讨论的 <strong>tcgen05 分组 GEMM</strong>（单 kernel + 2-SM 协作 + TMEM 分段累加）。三者的差别不在“是否融合”，而在融合之后<em>谁来承担小 M 维的代价</em>：逐专家 launch 把代价交给 CPU 启动开销与流水线气泡；普通 grouped GEMM 把代价交给 tile 利用率；tcgen05 分组 GEMM 把代价交给偏移表元数据与段间同步。选择问题因此可以重写成一句话：<strong>在你的专家 token 分布与专家数下，哪一种代价最先撞到瓶颈</strong>。</p>\n<p>判断的量化入口仍是利用率公式：</p>\n<div class=\"formula\">$$\\text{Util}=\\frac{\\sum_e M_e}{E\\cdot\\lceil \\max_e M_e/\\text{tile}_M\\rceil\\cdot \\text{tile}_M},\\quad \\text{GEMM 吞吐}\\propto \\text{Util}\\cdot\\text{TC 峰值}$$</div>\n<p>分子是真实有效行数，分母是按最大专家向上取整后的“分配容量”。这条式子说明两件事：Util 对 <em>max<sub>e</sub> M<sub>e</sub></em> 极其敏感（分母被最长的那一段钉死），而对专家数 E 只是线性摊薄。所以“专家多、单专家块小”并不必然低效——真正致命的是<strong>分布的长尾</strong>。举例：某 MoE 层 E=64，tile_M=128，若各专家 M<sub>e</sub> 均匀落在 100–140，分母约为 64×256=16384，分子约 7680，Util≈47%；若分布是少数专家 400+、多数专家 20–30，分母被抬到 64×512=32768，分子可能只有 5000 出头，Util 跌到 15% 量级——这时任何 kernel 侧优化都救不回来，必须回到路由侧（容量因子与令牌丢弃、专家选择路由，见同模块其他条目）。</p>\n\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-47\">四十七 · 决策表：四条判据与适用条件</h3>\n<p>下表把选择收敛为可执行的判据。注意表中“首选”不是绝对优劣，而是<em>在该条件下代价最先被吸收</em>的方案。</p>\n<table class=\"mini\">\n<thead><tr><th>判据</th><th>逐专家 launch</th><th>普通 grouped GEMM</th><th>tcgen05 分组 GEMM</th></tr></thead>\n<tbody>\n<tr><td>单专家 M 维 ≪ tile_M（如 &lt;64）</td><td>利用率极低，且 launch 数 = E</td><td>尾部空转明显，2-SM 无法启用</td><td><strong>首选</strong>：2-SM 协作把小 M 拼成可打满的 MMA</td></tr>\n<tr><td>专家 token 分布长尾严重</td><td>长尾专家自身仍低效，但短专家不受牵连</td><td>分母被 max 钉死，整体 Util 崩塌</td><td>同样受 max 钉死，需先做路由侧削峰</td></tr>\n<tr><td>专家数 E 很大（数十至上百）</td><td>CPU 侧 launch 开销与气泡线性增长</td><td>段元数据中等</td><td>偏移表与段元数据线性膨胀，占用率下降</td></tr>\n<tr><td>层时延 SLO 紧、batch 小</td><td>气泡占比高，尾延迟差</td><td>可用</td><td><strong>首选</strong>：单 kernel 消除气泡，段间同步是唯一风险</td></tr>\n<tr><td>量化叠加（NVFP4/FP8）</td><td>每专家独立量化配置，灵活</td><td>支持</td><td>支持，且 TMEM 分段累加与微缩放兼容</td></tr>\n</tbody>\n</table>\n<p>把表读成决策树更实用：<strong>第一步看 max<sub>e</sub> M<sub>e</sub> 与 tile_M 的比值</strong>——若最大专家都填不满一个 tile，逐专家 launch 与普通 grouped GEMM 都注定低效，直接进 tcgen05 分组 GEMM；<strong>第二步看分布离散度</strong>——若 max/mean 超过数倍，先回到路由侧处理，再谈 kernel；<strong>第三步看 E 与占用率</strong>——E 增大时偏移表吃寄存器与共享内存，此时宁可退回普通 grouped GEMM 换取占用率，或用分离式专家并行把专家分散到不同 rank（见同模块分离式专家并行条目）。</p>\n\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-48\">四十八 · 段间同步：tcgen05 方案独有的选择维度</h3>\n<p>前文已述机制步骤，这里只补一个选型时必须计入的隐性成本：<strong>段切换的同步代价</strong>。tcgen05 分组 GEMM 在每个专家段边界要做三件事——切 B 权重指针、TMEM 累加器分段清零、等待上一段结果写回。伪代码思路如下：</p>\n<div class=\"formula\">$$\\text{for } s \\text{ in segments: } \\text{wait}(s-1 \\text{ store});\\ \\text{TMEM.clear}(s);\\ \\text{MMA}(A[m_s:m_{s+1}], B_s \\rightarrow \\text{TMEM}_s);\\ \\text{store}(Y[m_s:m_{s+1}])$$</div>\n<p>若把 <em>wait</em> 放在 MMA 之前串行执行，段间就插入气泡，单 kernel 融合的收益被抵消——这正是失败模式里“同步不当”的那一条。工程上的对照判据是：<strong>当专家段平均长度接近或小于单次 MMA 的流水深度时，段间气泡占比上升，此时普通 grouped GEMM（段间无跨 SM 同步）反而更稳</strong>；反之，段较长（数百 token）时气泡被摊薄，tcgen05 的 2-SM 协作收益占主导。代价侧的具体体现是：段间同步让单层 GEMM 的时延不再只由 TC 峰值决定，而由 <em>TC 时间 + 段数 × 同步开销</em> 决定，E 越大这项越显著。</p>\n<p>一个具体例子：E=32、每段平均 256 token、tile_M=128 的层，段数 32、每段两个 tile，同步开销被 32 段摊薄后相对可控；而 E=128、每段平均 24 token 的层，段数翻四倍、每段不足一个 tile，同步与清零的频率压过计算本身，此时应优先考虑合并专家（减少 E）或改用无丢弃块稀疏分组 GEMM（见同模块对应条目），而不是硬上 tcgen05 分段。</p>\n\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-49\">四十九 · 与量化、KV、并行的交叉适用条件</h3>\n<p>选型不能只看 GEMM 本身，还要看它与相邻子系统的耦合。三条交叉判据：</p>\n<ul>\n<li><strong>与量化的耦合</strong>：NVFP4/FP8 微缩放量化把权重与激活压到更低位宽，K 维上的缩放因子让 MMA 的有效吞吐提升，但同时缩小了单次 MMA 的计算时间——这意味着<em>段间同步开销在总时延中的占比上升</em>。因此在低精度下，tcgen05 分组 GEMM 的适用门槛（段长度）比 BF16 时更高，短段场景更应倾向普通 grouped GEMM 或融合大核（见量化 MoE 解码融合大核条目）。</li>\n<li><strong>与显存共存的耦合</strong>：分页 KV 与专家权重共存时，专家权重的驻留布局决定了 B 指针切换的代价。若专家权重按段连续排布，切指针近乎零成本；若权重被分页打散，每次段切换都要重算地址，偏移表的寄存器压力进一步上升。适用条件是<strong>专家权重布局与段顺序对齐</strong>，否则应先做权重重排再启用本方案。</li>\n<li><strong>与并行的耦合</strong>：分离式专家并行把专家切到不同 rank，单 rank 上的 E 变小、段变长，恰好落在 tcgen05 分组 GEMM 的甜点区；而张量并行下每 rank 的 M 维被切分，单专家 M 更小，2-SM 协作的必要性上升。判断口径是：<strong>每 rank 的有效段长度</strong>而非全局段长度，才是选型依据。</li>\n</ul>\n\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-50\">五十 · 选型后的容量口径：把 Util 换算成 SLO</h3>\n<p>决策表给出方向后，还需要一个把选择落到容量规划上的换算。单层 GEMM 的有效算力为 <em>Util × TC 峰值</em>，因此单层时延可写成：</p>\n<div class=\"formula\">$$T_{\\text{layer}}\\approx\\frac{2\\cdot M_{\\text{total}}\\cdot K\\cdot N}{\\text{Util}\\cdot \\text{TC}_{\\text{peak}}}+E\\cdot t_{\\text{sync}}$$</div>\n<p>第二项是分段同步的固定开销，它随 E 线性增长而与 M 无关——这正是“专家数增多时占用率下降”在时延上的镜像。容量规划的含义是：当 batch 增大使 M<sub>total</sub> 上升时，第一项线性增长、第二项不变，tcgen05 方案的相对优势扩大；当 batch 很小（解码期单 token 级）时，第一项极小、第二项主导，此时融合大核或投机解码（见 MoE 投机解码条目）才是提效主线，分组 GEMM 的选型退居次要。换句话说，<strong>本方案的适用区间是“预填与中等 batch 解码”</strong>，而不是极低 batch 的逐 token 场景。</p>\n<p>一个工程判断的例子：若某层在目标 SLO 下允许的时延预算为固定值，而实测 Util 只有三成，则把预算的一半以上花在了空转 tile 上；此时正确的动作不是调 kernel 参数，而是先估算“把 max<sub>e</sub> M<sub>e</sub> 削到均值两倍以内”能把 Util 抬到多少，再决定是否值得为路由侧改动付出丢弃令牌的精度代价。这条换算把 kernel 选型与路由策略绑在同一个预算里，避免两边各自优化却互相抵消。</p>\n\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-51\">五十一 · 边界条件的硬判据</h3>\n<p>最后给出三条可以写进评审清单的硬判据，用于在方案评审时快速否决不合适的选型。<strong>其一，段长判据</strong>：若平均段长小于 tile_M 的一半且 E 超过数十，tcgen05 分组 GEMM 的段间同步与偏移表开销会吃掉 2-SM 协作的收益，应改用普通 grouped GEMM 或先合并专家。<strong>其二，分布判据</strong>：若 max<sub>e</sub> M<sub>e</sub> 超过均值数倍，任何 kernel 侧方案的 Util 都被分母钉死，选型讨论应暂停，先处理路由侧的长尾。<strong>其三，占用率判据</strong>：偏移表与段元数据随 E 线性占用寄存器与共享内存，当 E 增大到使占用率跌破可接受水位时，单 kernel 融合的收益被并发度损失抵消，此时分离式专家并行把 E 分摊到多 rank 是更稳的出路。三条判据的共同点是：它们都不问“哪个 kernel 更快”，而问“<em>哪一项代价在当前形状下最先饱和</em>”——这正是分组 GEMM 同族算法选型的全部要义。</p>\n\n<h3 id=\"alg-grouped-gemm-tcgen05-sec-52\">五十二 · 分组 GEMM 的邻域坐标：何时选它，何时换手</h3>\n<p>把这条路径放回同族算法的坐标系里，它的定位由两个变量决定：专家数与单专家 token 块相对 tile 的比值。逐专家 launch 的边界很清楚——当每专家 token 数足以填满一个 tile 且专家总数不多时，逐专家 launch 的 CPU 启动开销可以被计算掩盖，其调度逻辑最简单、调试成本最低，此时分组 GEMM 的偏移表维护反而是净负担。普通 grouped GEMM（不带 2-SM 协作）在单专家 M 维接近或超过 tile_M 时与本节方案等价，但一旦 M 维小于 tile_M，单 SM 的 MMA 无法打满张量核心，本节方案的 2-SM 协作就成为必要补偿。而完全动态的 token 路由式实现（每 token 独立寻址权重）在专家数极多、单专家块极碎时能避免拼接矩阵的尾部浪费，代价是权重访存不连续、难以复用 TMEM 累加器。</p>\n<p>选择判据可以写成一条不等式。设专家数为 $E$，第 $e$ 个专家的 token 数为 $M_e$，则拼接方案的利用率为</p>\n<div class=\"formula\">$$\\text{Util}=\\frac{\\sum_e M_e}{E\\cdot\\lceil \\max_e M_e/\\text{tile}_M\\rceil\\cdot \\text{tile}_M}$$</div>\n<p>分子是有效计算量，分母是按最大专家段对齐后分配的总 tile 容量。当 $\\max_e M_e$ 远大于 $\\min_e M_e$ 时，分母被最长段撑大，Util 迅速下滑；工程上以 Util 是否高于约一半作为分水岭——低于此值，2-SM 协作带来的张量核心填充收益会被尾部空转吃掉，此时应转向按 token 动态路由或对专家做二次分桶。反之，当 $E$ 大而各 $M_e$ 相近且都小于 tile_M 时，本节方案是唯一能同时消除 launch 气泡与打满 TC 的形态。吞吐关系 $\\text{GEMM 吞吐}\\propto \\text{Util}\\cdot\\text{TC 峰值}$ 说明这两项必须同时成立，任何一项塌陷都直接反映为单层时延超标。</p>\n<table class=\"mini\"><thead><tr><th>邻域算法</th><th>适用条件</th><th>主要代价</th><th>失效信号</th></tr></thead><tbody><tr><td>逐专家 launch</td><td>专家少、单专家 M 维 ≥ tile_M</td><td>CPU 启动开销、流水线气泡</td><td>专家数上升后 launch 间隔可见</td></tr><tr><td>普通 grouped GEMM</td><td>单专家 M 维接近 tile_M</td><td>小 M 维下 TC 填充不足</td><td>Util 随专家变小而下降</td></tr><tr><td>本节：tcgen05 分组 + 2-SM</td><td>专家多、单专家块偏小且分布较均</td><td>偏移表膨胀、尾部浪费</td><td>Util &lt; 50%、占用率下降</td></tr><tr><td>动态 token 路由</td><td>专家极多、块极碎、分布极不均</td><td>权重访存不连续、累加器复用差</td><td>带宽成为瓶颈而非 TC</td></tr></tbody></table>\n<p>系统代价要按层核算而非按 kernel 核算。偏移表使寄存器与共享内存压力随专家数线性增长，专家数增大到一定程度会压低 occupancy，进而削弱 2-SM 协作本来要争取的并行度——这是一条自我抵消的曲线，规模上限由片上资源而非算法本身决定，材料未给出具体专家数阈值，部署时必须实测占用率拐点。另一处隐性代价在段间：切换 $B_s$ 权重指针与 TMEM 分段清零若与 MMA 流水同步不当，会在每段边界插入气泡，单 kernel 融合省下的 launch 开销被段间空转逐段蚕食。工程判断是：先用 Util 公式估算本层分布下的上限，再看偏移表带来的占用率损失是否可接受，最后用段边界气泡的实测值决定是否值得保留融合；三项中任一不达标，就应把该层退回逐专家 launch 或改用动态路由，而不是靠调 tile_M 硬撑。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2024 · MoE路由与容量因子</td></tr><tr><td>解决什么</td><td>MoE 每个专家是独立的小矩阵乘，逐专家 launch 导致 kernel 启动开销与 tile 利用率低下，Blac…</td></tr><tr><td>一句话机制</td><td>把所有专家的 token 块拼成一个大 M 维的 grouped GEMM，用 tcgen05 的 2-SM 协作与 …</td></tr><tr><td>代价与失效</td><td>专家 token 数差异大时 tile 尾部浪费严重，Util 可能低于 50%；需要为每段维护偏移表，寄存器与共享内存压力随专家数线性增长</td></tr><tr><td>后继</td><td>双相专家预取与缓存</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-grouped-gemm-tcgen05 · 共 8 个片段</p>\n";break;}}})();
